const BASE32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
const newTotpSecret=()=>{const bytes=crypto.randomBytes(20);let bits='',out='';for(const b of bytes)bits+=b.toString(2).padStart(8,'0');for(let i=0;i<bits.length;i+=5)out+=BASE32[parseInt(bits.slice(i,i+5).padEnd(5,'0'),2)];return out;};
const decodeBase32=(value:string)=>{const clean=value.toUpperCase().replace(/[^A-Z2-7]/g,'');let bits='';for(const c of clean){const n=BASE32.indexOf(c);if(n<0)throw new Error('Chave TOTP inválida');bits+=n.toString(2).padStart(5,'0');}const bytes:number[]=[];for(let i=0;i+8<=bits.length;i+=8)bytes.push(parseInt(bits.slice(i,i+8),2));return Buffer.from(bytes);};
const totpCode=(secret:string,at=Date.now())=>{const counter=BigInt(Math.floor(at/30000)),buf=Buffer.alloc(8);buf.writeBigUInt64BE(counter);const hash=crypto.createHmac('sha1',decodeBase32(secret)).update(buf).digest(),offset=hash[hash.length-1]&15,value=(hash.readUInt32BE(offset)&0x7fffffff)%1000000;return String(value).padStart(6,'0');};
const verifyTotp=(secret:string,code:string)=>{const cleaned=String(code||'').replace(/\D/g,'');if(!/^\d{6}$/.test(cleaned))return false;for(const drift of [-1,0,1]){const a=Buffer.from(totpCode(secret,Date.now()+drift*30000)),b=Buffer.from(cleaned);if(a.length===b.length&&crypto.timingSafeEqual(a,b))return true;}return false;};
const encrypt = (value:string) => { const iv=crypto.randomBytes(12); const c=crypto.createCipheriv('aes-256-gcm',BIO_KEY,iv); const enc=Buffer.concat([c.update(value,'utf8'),c.final()]); return `${iv.toString('base64url')}.${c.getAuthTag().toString('base64url')}.${enc.toString('base64url')}`; };
const decrypt = (value:string) => { const [ivS,tagS,dataS]=value.split('.'); const d=crypto.createDecipheriv('aes-256-gcm',BIO_KEY,Buffer.from(ivS,'base64url')); d.setAuthTag(Buffer.from(tagS,'base64url')); return Buffer.concat([d.update(Buffer.from(dataS,'base64url')),d.final()]).toString('utf8'); };
const PIX_KEY_ENCRYPTION_KEY=Buffer.from(crypto.hkdfSync('sha256',BIO_KEY,Buffer.from('multigym-pix-wallet-v1'),Buffer.from('withdrawal-pix-key'),32));
const encryptPixKey=(value:string)=>{const iv=crypto.randomBytes(12),c=crypto.createCipheriv('aes-256-gcm',PIX_KEY_ENCRYPTION_KEY,iv),enc=Buffer.concat([c.update(value,'utf8'),c.final()]);return `${iv.toString('base64url')}.${c.getAuthTag().toString('base64url')}.${enc.toString('base64url')}`;};
const decryptPixKey=(value:string)=>{const [ivS,tagS,dataS]=value.split('.'),d=crypto.createDecipheriv('aes-256-gcm',PIX_KEY_ENCRYPTION_KEY,Buffer.from(ivS,'base64url'));d.setAuthTag(Buffer.from(tagS,'base64url'));return Buffer.concat([d.update(Buffer.from(dataS,'base64url')),d.final()]).toString('utf8')};
const money = (n:any) => Number(Number(n||0).toFixed(2));
const luhnValid=(digits:string)=>{let sum=0,double=false;for(let i=digits.length-1;i>=0;i--){let d=Number(digits[i]);if(double){d*=2;if(d>9)d-=9;}sum+=d;double=!double;}return sum%10===0;};
const slugify = (s:string) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90);
const planTier=(sub:any)=>{if(!sub||['trial','grandfathered'].includes(String(sub.status||'')))return 'premium';const code=String(sub.plan_code||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z]/g,'');const name=String(sub.plan_name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z]/g,'');const raw=code||name;if(raw.includes('premium'))return 'premium';if(raw.includes('essencial')||raw.includes('essential'))return 'essential';if(raw.includes('basico')||raw.includes('basic'))return 'basic';return 'basic';};
