const featureForPath=(path:string,method:string):string|null=>{const p=path.split('?')[0];if(p==='/api/exercises'||p.startsWith('/api/exercises/')||p==='/api/workouts'||p.startsWith('/api/workouts/')||p==='/student-api/workout-history'||p.startsWith('/student-api/workouts/'))return 'workouts';if(p==='/api/products'||p.startsWith('/api/products/'))return 'products';if(p==='/api/services'||p.startsWith('/api/services/'))return 'services';if(p==='/api/payments/asaas-checkout'||/^\/api\/payments\/[^/]+\/asaas-status$/.test(p)||/^\/api\/enrollments\/[^/]+\/payment$/.test(p)||p==='/api/online-billing/settings'||p==='/student-api/monthly-payment'||p.startsWith('/student-api/monthly-payment/'))return 'online_billing';if(p==='/api/cash'||p.startsWith('/api/cash/')||p==='/api/sales'||(p==='/api/payments'&&method==='POST'))return 'cash';if(p==='/api/appointments'||p.startsWith('/api/appointments/'))return 'agenda';if(p.startsWith('/student-api/nutrigym'))return 'nutrigym';if(p.startsWith('/student-api/personalgym'))return 'personalgym';return null;};
const planDenied=(feature:string)=>({error:'Este recurso não está incluído no seu plano. Atualize seu plano para acessar esta função.',upgrade_required:true,feature,upgrade_url:'/?billing=plans'});
