const billingExemptPaths = new Set(['/api/me','/api/auth/logout','/api/saas/status','/api/saas/plans','/api/saas/checkout','/api/master/saas/gyms','/api/master/saas/plans']);
const requireAuth = async (req:Req, reply:FastifyReply) => {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return reply.code(401).send({error:'Não autenticado'});
  const token=header.slice(7); const row=await one(`SELECT u.id,u.gym_id,u.name,u.email,u.role,u.status,g.name gym_name,(g.owner_user_id=u.id) AS is_gym_owner,u.totp_enabled FROM sessions s JOIN users u ON u.id=s.user_id JOIN gyms g ON g.id=s.gym_id WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.expires_at>now() AND u.status='active' AND g.active=true`,[hashToken(token)]);
  if(!row) return reply.code(401).send({error:'Sessão expirada'}); req.user=row;
  if(!billingExemptPaths.has(req.url.split('?')[0])) {
    const entitlement=await one(`SELECT s.status,s.expires_at,s.trial_started_at,p.name plan_name,p.plan_code,p.max_users FROM gym_saas_subscriptions s LEFT JOIN gym_saas_plans p ON p.id=s.plan_id WHERE s.gym_id=$1 ORDER BY s.updated_at DESC LIMIT 1`,[row.gym_id]);
    const allowed=!entitlement || (entitlement.status==='grandfathered'||(!entitlement.expires_at&&entitlement.status==='active')||(entitlement.trial_started_at&&entitlement.expires_at&&new Date(entitlement.expires_at)>new Date())||(entitlement.expires_at&&(()=>{const cutoff=new Date(`${String(entitlement.expires_at).slice(0,10)}T23:59:59-03:00`);if(entitlement.status==='active'&&cutoff>=new Date())return true;cutoff.setDate(cutoff.getDate()+5);return cutoff>=new Date()&&['active','manual','past_due','cancelled'].includes(entitlement.status)})()));
    if(!allowed)return reply.code(402).send({error:'Plano MultiGym pendente ou vencido. Acesse a área Plano e cobrança para regularizar.',billing_required:true});const tier=planTier(entitlement),feature=featureForPath(req.url,req.method),path=req.url.split('?')[0];if(tier==='basic'&&feature==='cash'){const bodyValue=(req.body||{}) as any;const isEnrollmentReceipt=path==='/api/payments'&&Boolean(bodyValue.enrollment_id)&&['membership','enrollment'].includes(String(bodyValue.category||'membership'));const allowedCashPaths=new Set(['/api/cash/current','/api/cash/open','/api/cash/close']);if(!allowedCashPaths.has(path)&&!isEnrollmentReceipt)return reply.code(403).send({...planDenied('cash'),error:'No Básico, o caixa fica disponível somente para recebimentos de matrículas. Atualize seu plano para liberar as demais funções do caixa.',feature:'cash'});}if(feature&&(lockedPlanFeatures[tier]||[]).includes(feature))return reply.code(403).send(planDenied(feature));
  }
};
