app.get('/api/auth/human-challenge',{config:{rateLimit:{max:10,timeWindow:'10 minutes'}}},async()=>{await q(`DELETE FROM auth_visual_challenges WHERE expires_at<now()-interval '1 day'`);await q(`DELETE FROM auth_human_challenge_tokens WHERE expires_at<now()-interval '1 day'`);const answer=humanChallengeImages[crypto.randomInt(humanChallengeImages.length)],id=newToken(),exp=Date.now()+5*60*1000,labels=Array.from({length:8},(_,i)=>({id:newToken(8),...(humanChallengeImages.filter(x=>x.label!==answer.label)[crypto.randomInt(humanChallengeImages.length-1)])})),positions=secureShuffle([0,1,2,3,4,5,6,7]).slice(0,2+crypto.randomInt(3));for(const i of positions)labels[i]={id:labels[i].id,...answer};const options=labels.map(({id,symbol})=>({id,symbol}));await q(`INSERT INTO auth_visual_challenges(id_hash,answer,correct_option_ids,expires_at) VALUES($1,$2,$3,to_timestamp($4/1000.0))`,[hashToken(id),answer.label,JSON.stringify(positions.map(i=>labels[i].id).sort()),exp]);return {challenge_id:id,expires_at:exp,prompt:`Selecione todas as imagens de ${answer.label}`,options};});
app.post('/api/auth/human-challenge/verify',{config:{rateLimit:{max:8,timeWindow:'10 minutes'}}},async(req,reply)=>{const b=body(req),id=String(b.challenge_id||''),exp=Number(b.expires_at),selected=Array.isArray(b.selected)?b.selected.map(String):[];if(!id||id.length<30||id.length>100||!Number.isFinite(exp)||!Array.isArray(b.selected)||selected.length>8||Date.now()>exp||Date.now()<exp-5*60*1000)return reply.code(400).send({error:'Verificação expirada. Gere um novo desafio.'});const claimed=await one(`UPDATE auth_visual_challenges SET attempts=attempts+1 WHERE id_hash=$1 AND verified_at IS NULL AND failed_at IS NULL AND attempts=0 AND expires_at>now() RETURNING answer,correct_option_ids`,[hashToken(id)]);if(!claimed)return reply.code(400).send({error:'Desafio expirado ou já utilizado. Gere um novo.'});const canonical=(Array.isArray(claimed.correct_option_ids)?claimed.correct_option_ids:JSON.parse(claimed.correct_option_ids)).map(String).sort(),submitted=Array.from(new Set(selected)).sort();if(submitted.some(x=>!/^[-_A-Za-z0-9]{8,64}$/.test(x))||canonical.length!==submitted.length||canonical.some((x,i)=>x!==submitted[i])){await q(`UPDATE auth_visual_challenges SET failed_at=now() WHERE id_hash=$1 AND verified_at IS NULL`,[hashToken(id)]);return reply.code(400).send({error:'A resposta não corresponde. Gere um novo desafio.'});}const marked=await one(`UPDATE auth_visual_challenges SET verified_at=now() WHERE id_hash=$1 AND verified_at IS NULL AND failed_at IS NULL AND expires_at>now() RETURNING id_hash`,[hashToken(id)]);if(!marked)return reply.code(400).send({error:'Desafio expirado ou já utilizado. Gere um novo.'});const token=newToken(),tokenExp=Date.now()+5*60*1000;await q(`INSERT INTO auth_human_challenge_tokens(token_hash,challenge_id_hash,expires_at) VALUES($1,$2,to_timestamp($3/1000.0))`,[hashToken(token),hashToken(id),tokenExp]);return {challenge_id:id,verification_token:token,verification_expires_at:tokenExp};});
app.post('/api/auth/register',{config:{rateLimit:{max:5,timeWindow:'10 minutes'}}},async(req,reply)=>{
  const b=body(req);if(String(b.company_website||'').trim())return reply.code(400).send({error:'Não foi possível validar a solicitação.'});if(!b.challenge_token||!Number.isFinite(Number(b.challenge_expires_at))||Date.now()>Number(b.challenge_expires_at)||Date.now()<Number(b.challenge_expires_at)-5*60*1000)return reply.code(400).send({error:'Conclua a verificação de segurança antes de criar a academia.'});
  if(!b.gymName||!b.name||!b.email||!b.password) return reply.code(400).send({error:'Preencha academia, nome, e-mail e senha'});
  if(String(b.password).length<8) return reply.code(400).send({error:'A senha deve ter pelo menos 8 caracteres'});
  const client=await pool.connect();
  try { await client.query('BEGIN'); const humanClaim=await client.query(`UPDATE auth_human_challenge_tokens SET used_at=now() WHERE token_hash=$1 AND challenge_id_hash=$2 AND used_at IS NULL AND expires_at>now() AND EXISTS(SELECT 1 FROM auth_visual_challenges c WHERE c.id_hash=auth_human_challenge_tokens.challenge_id_hash AND c.verified_at IS NOT NULL AND c.expires_at>now()) RETURNING token_hash`,[hashToken(String(b.challenge_token)),hashToken(String(b.challenge_id||''))]);if(!humanClaim.rowCount)throw new Error('A verificação já foi usada ou expirou. Gere um novo desafio.');const slugBase=slugify(b.gymName)||'academia'; let slug=slugBase; let i=1; while((await client.query('SELECT 1 FROM gyms WHERE slug=$1',[slug])).rowCount) slug=`${slugBase}-${i++}`;
    const gym=(await client.query(`INSERT INTO gyms(name,slug,email,phone) VALUES($1,$2,$3,$4) RETURNING *`,[b.gymName,slug,b.email,b.phone||null])).rows[0];
    const passwordHash=await argon2.hash(b.password); const user=(await client.query(`INSERT INTO users(gym_id,name,email,password_hash,role) VALUES($1,$2,$3,$4,'admin') RETURNING id,name,email,role`,[gym.id,b.name,b.email.toLowerCase(),passwordHash])).rows[0]; await client.query(`UPDATE gyms SET owner_user_id=$2 WHERE id=$1`,[gym.id,user.id]);
    await client.query(`INSERT INTO plans(gym_id,name,price,duration_days,description) VALUES ($1,'Mensal',100,30,'Plano mensal padrão'),($1,'Trimestral',270,90,'Plano trimestral'),($1,'Semestral',500,180,'Plano semestral') ON CONFLICT(gym_id,name) DO NOTHING`,[gym.id]); await client.query(`INSERT INTO gym_saas_subscriptions(gym_id,status,source,trial_started_at,expires_at) VALUES($1,'trial','trial',now(),now()+interval '10 days') ON CONFLICT(gym_id) DO NOTHING`,[gym.id]);
    await ensureExerciseLibrary(gym.id,client); await client.query('COMMIT'); const token=newToken(); await q(`INSERT INTO sessions(user_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+($4||' days')::interval)`,[user.id,gym.id,hashToken(token),SESSION_DAYS]);
    return reply.send({token,user:{...user,gym_id:gym.id,gym_name:gym.name,gym_slug:gym.slug,is_gym_owner:true,totp_enabled:false}});
  } catch(e){ await client.query('ROLLBACK'); app.log.error(e); return reply.code(400).send({error:'Não foi possível criar a academia. Verifique os dados.'}); } finally{client.release();}
});

app.post('/api/auth/login',{config:{rateLimit:{max:10,timeWindow:'10 minutes'}}},async(req,reply)=>{const b=body(req),email=String(b.email||'').trim().toLowerCase(),slug=String(b.gym_slug||b.gymSlug||'').trim().toLowerCase();if(!email||!b.password)return reply.code(400).send({error:'Informe e-mail e senha.'});const users=await q(`SELECT u.*,g.name gym_name,g.slug gym_slug,(g.owner_user_id=u.id) AS is_gym_owner FROM users u JOIN gyms g ON g.id=u.gym_id WHERE lower(u.email)=lower($1) AND u.status='active' AND ($2='' OR g.slug=$2)`,[email,slug]);if(!users.length||(!slug&&users.length>1))return reply.code(401).send({error:users.length>1?'Informe o identificador da academia.':'E-mail ou senha inválidos'});const u=users[0],gymState=await one(`SELECT active FROM gyms WHERE id=$1`,[u.gym_id]);if(u.locked_at)return reply.code(423).send({error:'A senha foi bloqueada por excesso de tentativas. Entre em contato com o suporte.'});if(!gymState?.active)return reply.code(401).send({error:'E-mail ou senha inválidos'});if(!(await argon2.verify(u.password_hash,b.password))){const failed=await one(`UPDATE users SET failed_login_attempts=failed_login_attempts+1,locked_at=CASE WHEN failed_login_attempts+1>=2 THEN now() ELSE locked_at END WHERE id=$1 RETURNING failed_login_attempts,locked_at`,[u.id]);if(failed?.locked_at){await q(`UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND revoked_at IS NULL`,[u.id]);return reply.code(423).send({error:'A senha foi bloqueada por excesso de tentativas. Entre em contato com o suporte.'});}return reply.code(401).send({error:'E-mail ou senha inválidos'});}await q(`UPDATE users SET failed_login_attempts=0,locked_at=NULL WHERE id=$1`,[u.id]);if(u.totp_enabled){const code=String(b.totp_code||'');if(!code){const challenge=newToken();await q(`INSERT INTO auth_login_challenges(user_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '5 minutes')`,[u.id,u.gym_id,hashToken(challenge)]);return reply.code(202).send({requires_2fa:true,challenge_token:challenge});}let secret='';try{secret=decrypt(u.totp_secret_encrypted||'')}catch{return reply.code(401).send({error:'A verificação em duas etapas precisa ser reconfigurada.'});}if(!verifyTotp(secret,code))return reply.code(401).send({error:'Código de verificação inválido ou expirado.'});}const token=newToken();await q(`INSERT INTO sessions(user_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+($4||' days')::interval)`,[u.id,u.gym_id,hashToken(token),SESSION_DAYS]);await q(`UPDATE users SET last_login_at=now() WHERE id=$1`,[u.id]);return {token,user:{id:u.id,gym_id:u.gym_id,name:u.name,email:u.email,role:u.role,gym_name:u.gym_name,gym_slug:u.gym_slug,is_gym_owner:Boolean(u.is_gym_owner),totp_enabled:Boolean(u.totp_enabled)}};});
app.post('/api/auth/verify-2fa',{config:{rateLimit:{max:10,timeWindow:'5 minutes'}}},async(req,reply)=>{const b=body(req),challengeToken=String(b.challenge_token||''),code=String(b.totp_code||'');if(!challengeToken||!code)return reply.code(400).send({error:'Informe o código do aplicativo autenticador.'});const challenge=await one(`SELECT c.id,c.user_id,c.gym_id,u.name,u.email,u.role,u.status,u.totp_enabled,u.totp_secret_encrypted,g.name gym_name,g.slug gym_slug,g.active,(g.owner_user_id=u.id) is_gym_owner FROM auth_login_challenges c JOIN users u ON u.id=c.user_id JOIN gyms g ON g.id=c.gym_id WHERE c.token_hash=$1 AND c.used_at IS NULL AND c.expires_at>now()`,[hashToken(challengeToken)]);if(!challenge||challenge.status!=='active'||!challenge.active||!challenge.totp_enabled)return reply.code(401).send({error:'A verificação expirou. Entre novamente.'});let secret='';try{secret=decrypt(challenge.totp_secret_encrypted||'')}catch{return reply.code(401).send({error:'A verificação em duas etapas precisa ser reconfigurada.'});}if(!verifyTotp(secret,code))return reply.code(401).send({error:'Código de verificação inválido ou expirado.'});const consumed=await one(`UPDATE auth_login_challenges SET used_at=now() WHERE id=$1 AND used_at IS NULL AND expires_at>now() RETURNING id`,[challenge.id]);if(!consumed)return reply.code(401).send({error:'A verificação já foi utilizada. Entre novamente.'});const token=newToken();await q(`INSERT INTO sessions(user_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+($4||' days')::interval)`,[challenge.user_id,challenge.gym_id,hashToken(token),SESSION_DAYS]);await q(`UPDATE users SET last_login_at=now() WHERE id=$1`,[challenge.user_id]);return {token,user:{id:challenge.user_id,gym_id:challenge.gym_id,name:challenge.name,email:challenge.email,role:challenge.role,gym_name:challenge.gym_name,gym_slug:challenge.gym_slug,is_gym_owner:Boolean(challenge.is_gym_owner),totp_enabled:true}};});
app.post('/api/auth/logout',{preHandler:requireAuth},async(req:Req,reply)=>{ const t=(req.headers.authorization||'').slice(7); await q(`UPDATE sessions SET revoked_at=now() WHERE token_hash=$1`,[hashToken(t)]); return {ok:true}; });
app.get('/api/me',{preHandler:requireAuth},async(req:Req)=>({user:req.user}));
type MasterReq = FastifyRequest & { master?: { id:string; email:string; must_change_password:boolean; password_expires_at:string|null; totp_enabled?:boolean } };
const requireMaster=async(req:MasterReq,reply:FastifyReply)=>{const h=req.headers.authorization||'';if(!h.startsWith('Bearer '))return reply.code(401).send({error:'Não autenticado'});const row=await one(`SELECT a.id,a.email,a.must_change_password,a.password_expires_at,a.totp_enabled FROM master_sessions s JOIN master_accounts a ON a.id=s.master_id WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.expires_at>now() AND a.status='active'`,[hashToken(h.slice(7))]);if(!row)return reply.code(401).send({error:'Sessão Master expirada'});if(row.must_change_password&&(!row.password_expires_at||new Date(row.password_expires_at)<=new Date()))return reply.code(403).send({error:'A senha temporária expirou. Reemita o acesso inicial.'});req.master=row;};
const requireMasterReady=async(req:MasterReq,reply:FastifyReply)=>{if(req.master?.must_change_password)return reply.code(403).send({error:'Altere a senha provisória antes de continuar.'});};
app.post('/api/master/login',{config:{rateLimit:{max:5,timeWindow:'10 minutes'}}},async(req,reply)=>{const b=body(req),email=String(b.email||'').trim().toLowerCase();if(email!=='fabio17dejesusjunior@gmail.com'||!b.password)return reply.code(400).send({error:'Informe o e-mail Master e a senha.'});const a=await one(`SELECT id,email,password_hash,must_change_password,password_expires_at,status,totp_enabled FROM master_accounts WHERE email=$1`,[email]);if(!a||a.status!=='active')return reply.code(401).send({error:'Credenciais inválidas.'});if(a.must_change_password&&(!a.password_expires_at||new Date(a.password_expires_at)<=new Date()))return reply.code(403).send({error:'A senha provisória expirou. Reemita o acesso inicial.'});if(!(await argon2.verify(a.password_hash,String(b.password))))return reply.code(401).send({error:'Credenciais inválidas.'});if(a.totp_enabled){const challenge=newToken();await q(`INSERT INTO master_login_challenges(master_id,token_hash,expires_at) VALUES($1,$2,now()+interval '5 minutes')`,[a.id,hashToken(challenge)]);return reply.code(202).send({requires_2fa:true,challenge_token:challenge});}const token=newToken();await q(`INSERT INTO master_sessions(master_id,token_hash,expires_at) VALUES($1,$2,now()+interval '12 hours')`,[a.id,hashToken(token)]);return {token,master:{id:a.id,email:a.email,must_change_password:a.must_change_password,password_expires_at:a.password_expires_at,totp_enabled:Boolean(a.totp_enabled)}};});
app.post('/api/master/verify-2fa',{config:{rateLimit:{max:8,timeWindow:'5 minutes'}}},async(req,reply)=>{const b=body(req),challenge=await one(`SELECT c.id,c.master_id,a.email,a.must_change_password,a.password_expires_at,a.status,a.totp_enabled,a.totp_secret_encrypted FROM master_login_challenges c JOIN master_accounts a ON a.id=c.master_id WHERE c.token_hash=$1 AND c.used_at IS NULL AND c.expires_at>now()`,[hashToken(String(b.challenge_token||''))]);if(!challenge||challenge.status!=='active'||!challenge.totp_enabled)return reply.code(401).send({error:'A verificação expirou. Entre novamente.'});let secret='';try{secret=decrypt(challenge.totp_secret_encrypted||'')}catch{return reply.code(401).send({error:'A verificação em duas etapas precisa ser reconfigurada.'});}if(!verifyTotp(secret,String(b.totp_code||'')))return reply.code(401).send({error:'Código inválido ou expirado.'});const used=await one(`UPDATE master_login_challenges SET used_at=now() WHERE id=$1 AND used_at IS NULL AND expires_at>now() RETURNING id`,[challenge.id]);if(!used)return reply.code(401).send({error:'A verificação já foi utilizada. Entre novamente.'});const token=newToken();await q(`INSERT INTO master_sessions(master_id,token_hash,expires_at) VALUES($1,$2,now()+interval '12 hours')`,[challenge.master_id,hashToken(token)]);return {token,master:{id:challenge.master_id,email:challenge.email,must_change_password:challenge.must_change_password,password_expires_at:challenge.password_expires_at,totp_enabled:true}};});
app.get('/api/master/security/totp',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq)=>({enabled:Boolean(req.master!.totp_enabled)}));
app.post('/api/master/security/totp/setup',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const pass=String(body(req).current_password||''),a=await one(`SELECT password_hash,totp_enabled FROM master_accounts WHERE id=$1`,[req.master!.id]);if(!a||!(await argon2.verify(a.password_hash,pass)))return reply.code(401).send({error:'Confirme sua senha Master atual.'});if(a.totp_enabled)return reply.code(409).send({error:'A verificação já está ativa. Desative-a antes de configurar novamente.'});const secret=newTotpSecret();await q(`UPDATE master_accounts SET totp_secret_encrypted=$1,updated_at=now() WHERE id=$2`,[encrypt(secret),req.master!.id]);const label=encodeURIComponent(`MultiGym Master:${req.master!.email}`),issuer=encodeURIComponent('MultiGym Master'),otpauth_url=`otpauth://totp/${label}?secret=${secret}&issuer=${issuer}&algorithm=SHA1&digits=6&period=30`;return {secret,otpauth_url};});
app.post('/api/master/security/totp/enable',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const a=await one(`SELECT totp_secret_encrypted FROM master_accounts WHERE id=$1`,[req.master!.id]);if(!a?.totp_secret_encrypted)return reply.code(400).send({error:'Inicie a configuração do aplicativo autenticador.'});let secret='';try{secret=decrypt(a.totp_secret_encrypted)}catch{return reply.code(400).send({error:'Não foi possível ler a configuração. Gere uma nova chave.'});}if(!verifyTotp(secret,String(body(req).totp_code||'')))return reply.code(400).send({error:'Código inválido. Confira a hora e a chave no aplicativo.'});await q(`UPDATE master_accounts SET totp_enabled=true,updated_at=now() WHERE id=$1`,[req.master!.id]);await q(`INSERT INTO master_audit_logs(master_id,action,metadata) VALUES($1,'master_totp_enabled','{}')`,[req.master!.id]);return {enabled:true};});
app.post('/api/master/security/totp/disable',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const b=body(req),a=await one(`SELECT password_hash,totp_enabled,totp_secret_encrypted FROM master_accounts WHERE id=$1`,[req.master!.id]);if(!a?.totp_enabled)return reply.code(400).send({error:'A verificação em duas etapas já está desativada.'});if(!(await argon2.verify(a.password_hash,String(b.password||''))))return reply.code(401).send({error:'Senha incorreta.'});let secret='';try{secret=decrypt(a.totp_secret_encrypted||'')}catch{return reply.code(401).send({error:'A chave precisa ser reconfigurada.'});}if(!verifyTotp(secret,String(b.totp_code||'')))return reply.code(401).send({error:'Código inválido.'});await q(`UPDATE master_accounts SET totp_secret_encrypted=NULL,totp_enabled=false,updated_at=now() WHERE id=$1`,[req.master!.id]);await q(`DELETE FROM master_login_challenges WHERE master_id=$1`,[req.master!.id]);await q(`INSERT INTO master_audit_logs(master_id,action,metadata) VALUES($1,'master_totp_disabled','{}')`,[req.master!.id]);return {enabled:false};});
app.get('/api/master/me',{preHandler:requireMaster},async(req:MasterReq)=>({master:req.master}));
app.get('/api/master/overview',{preHandler:[requireMaster,requireMasterReady]},async()=>{const [counts,db]=await Promise.all([one(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE g.active)::int active,COUNT(*) FILTER(WHERE NOT g.active)::int inactive,COUNT(*) FILTER(WHERE g.active AND s.status='trial' AND s.expires_at>now())::int trials,COUNT(*) FILTER(WHERE g.active AND (s.status IN ('past_due','cancelled') OR (s.expires_at IS NOT NULL AND s.expires_at<now() AND s.status<>'grandfathered')))::int attention FROM gyms g LEFT JOIN gym_saas_subscriptions s ON s.gym_id=g.id`),pool.query('SELECT 1').then(()=>true).catch(()=>false)]);const support=await one(`SELECT COUNT(*) FILTER(WHERE status='open')::int open,COUNT(*) FILTER(WHERE status='in_progress')::int in_progress FROM master_support_tickets`);return {generated_at:new Date().toISOString(),api:{ok:true,version:'2.0.0'},database:{ok:db},gyms:counts||{total:0,active:0,inactive:0,trials:0,attention:0},support:support||{open:0,in_progress:0}};});
app.get('/api/master/audit',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq)=>{const limit=Math.min(100,Math.max(1,Number((req.query as any)?.limit)||50));return q(`SELECT a.id,a.action,a.gym_id,g.name gym_name,a.metadata,a.created_at,m.email master_email FROM master_audit_logs a LEFT JOIN gyms g ON g.id=a.gym_id LEFT JOIN master_accounts m ON m.id=a.master_id ORDER BY a.created_at DESC LIMIT $1`,[limit]);});
app.get('/api/support/tickets',{preHandler:[requireAuth,requireSupportAccess]},async(req:Req)=>q(`SELECT t.id,t.subject,t.description,t.priority,t.status,t.created_at,t.updated_at,(SELECT count(*)::int FROM master_support_messages sm WHERE sm.ticket_id=t.id) message_count,(SELECT body FROM master_support_messages sm WHERE sm.ticket_id=t.id ORDER BY sm.created_at DESC LIMIT 1) last_message,(SELECT count(*)::int FROM master_support_messages sm WHERE sm.ticket_id=t.id AND sm.author_type='master' AND sm.created_at>COALESCE(t.gym_seen_at,t.created_at-interval '1 second')) unread_count FROM master_support_tickets t WHERE t.gym_id=$1 ORDER BY t.updated_at DESC LIMIT 100`,[req.user!.gym_id]));
app.post('/api/support/tickets',{preHandler:[requireAuth,requireSupportAccess]},async(req:Req,reply)=>{const b=body(req),subject=String(b.subject||'').trim().slice(0,160),description=String(b.description||'').trim().slice(0,5000),priority=String(b.priority||'normal');if(!subject||!description||!['low','normal','high'].includes(priority))return reply.code(400).send({error:'Informe assunto, descrição e prioridade válidos.'});const row=await one(`INSERT INTO master_support_tickets(gym_id,gym_name,subject,description,priority) SELECT g.id,g.name,$2,$3,$4 FROM gyms g WHERE g.id=$1 RETURNING id,subject,description,priority,status,created_at,updated_at`,[req.user!.gym_id,subject,description,priority]);if(!row)return reply.code(404).send({error:'Academia não encontrada.'});await q(`INSERT INTO master_support_messages(ticket_id,author_type,author_user_id,body) VALUES($1,'gym',$2,$3)`,[row.id,req.user!.id,description]);await q(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES(NULL,'support_ticket_created',$1,$2)`,[req.user!.gym_id,JSON.stringify({ticket_id:row.id,priority,created_by_role:req.user!.role})]);await q(`INSERT INTO notifications(gym_id,user_id,title,body) SELECT $1,id,'Novo chamado de suporte',left($2,180) FROM users WHERE gym_id=$1 AND role IN ('admin','manager') AND status='active' AND id<>$3`,[req.user!.gym_id,subject,req.user!.id]);return reply.code(201).send({...row,message_count:1,last_message:description});});
