app.post('/api/support/tickets/:id/messages',{preHandler:[requireAuth,requireSupportAccess]},async(req:Req,reply)=>{const id=String((req.params as any).id),text=String(body(req).body||'').trim().slice(0,5000);if(!text)return reply.code(400).send({error:'Escreva uma mensagem antes de enviar.'});const ticket=await one(`SELECT id FROM master_support_tickets WHERE id=$1 AND gym_id=$2`,[id,req.user!.gym_id]);if(!ticket)return reply.code(404).send({error:'Chamado não encontrado.'});const msg=await one(`INSERT INTO master_support_messages(ticket_id,author_type,author_user_id,body) VALUES($1,'gym',$2,$3) RETURNING id,author_type,body,created_at`,[id,req.user!.id,text]);await q(`UPDATE master_support_tickets SET status=CASE WHEN status='resolved' THEN 'open' ELSE status END,updated_at=now() WHERE id=$1`,[id]);await q(`INSERT INTO notifications(gym_id,user_id,title,body) SELECT $1,id,'Nova mensagem no suporte',left($2,180) FROM users WHERE gym_id=$1 AND role IN ('admin','manager') AND status='active' AND id<>$3`,[req.user!.gym_id,text,req.user!.id]);return reply.code(201).send({...msg,author_name:req.user!.name});});
