app.get('/api/master/support/tickets/:id/messages',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const id=String((req.params as any).id),ticket=await one(`SELECT id FROM master_support_tickets WHERE id=$1`,[id]);if(!ticket)return reply.code(404).send({error:'Chamado não encontrado.'});await q(`UPDATE master_support_tickets SET master_seen_at=now() WHERE id=$1`,[id]);return q(`SELECT m.id,m.author_type,m.body,m.created_at,CASE WHEN m.author_type='gym' THEN COALESCE(u.name,'Equipe da academia') ELSE 'Suporte MultiGym' END author_name FROM master_support_messages m LEFT JOIN users u ON u.id=m.author_user_id WHERE m.ticket_id=$1 ORDER BY m.created_at`,[id]);});
