app.get('/api/master/support/tickets',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq)=>{const status=String((req.query as any)?.status||'all');if(!['all','open','in_progress','resolved','closed'].includes(status))return [];return q(`SELECT t.id,t.gym_id,t.gym_name,t.subject,t.description,t.priority,t.status,t.master_note,t.locked_email,t.locked_account_type,t.created_at,t.updated_at,(SELECT count(*)::int FROM master_support_messages sm WHERE sm.ticket_id=t.id) message_count,(SELECT body FROM master_support_messages sm WHERE sm.ticket_id=t.id ORDER BY sm.created_at DESC LIMIT 1) last_message,(SELECT count(*)::int FROM master_support_messages sm WHERE sm.ticket_id=t.id AND sm.author_type='gym' AND sm.created_at>COALESCE(t.master_seen_at,t.created_at-interval '1 second')) unread_count FROM master_support_tickets t WHERE $1='all' OR t.status=$1 ORDER BY CASE t.priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END,t.updated_at DESC LIMIT 200`,[status]);});
app.patch('/api/master/support/tickets/:id',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const b=body(req),status=String(b.status||''),note=typeof b.master_note==='string'?b.master_note.trim().slice(0,5000):undefined;if(!['open','in_progress','resolved','closed'].includes(status))return reply.code(400).send({error:'Status de chamado inválido.'});const row=await one(`UPDATE master_support_tickets SET status=$1,master_note=COALESCE($2,master_note),updated_by=$3,updated_at=now() WHERE id=$4 RETURNING id,gym_id,gym_name,subject,description,priority,status,master_note,created_at,updated_at`,[status,note??null,req.master!.id,(req.params as any).id]);if(!row)return reply.code(404).send({error:'Chamado não encontrado.'});await q(`INSERT INTO notifications(gym_id,user_id,title,body) SELECT $1,id,'Chamado atualizado pelo suporte',left($2,180) FROM users WHERE gym_id=$1 AND role IN ('admin','manager') AND status='active'`,[row.gym_id,`${row.subject}: ${status}`]);await q(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES($1,'support_ticket_updated',$2,$3)`,[req.master!.id,row.gym_id,JSON.stringify({ticket_id:row.id,status})]);return row;});
app.post('/api/master/change-password',{preHandler:requireMaster},async(req:MasterReq,reply)=>{const p=String(body(req).new_password||'');if(p.length<12)return reply.code(400).send({error:'A nova senha precisa ter pelo menos 12 caracteres.'});const hash=await argon2.hash(p),token=(req.headers.authorization||'').slice(7);await q(`UPDATE master_accounts SET password_hash=$1,must_change_password=false,password_expires_at=NULL,updated_at=now() WHERE id=$2`,[hash,req.master!.id]);await q(`UPDATE master_sessions SET revoked_at=now() WHERE master_id=$1 AND token_hash<>$2 AND revoked_at IS NULL`,[req.master!.id,hashToken(token)]);return {ok:true};});
app.get('/api/master/monthly-wallet/withdrawals',{preHandler:[requireMaster,requireMasterReady]},async()=>{const rows=await q(`SELECT w.*,g.name gym_name,g.slug gym_slug FROM gym_monthly_wallet_withdrawals w JOIN gyms g ON g.id=w.gym_id ORDER BY CASE w.status WHEN 'pending' THEN 0 ELSE 1 END,w.requested_at DESC LIMIT 500`);return rows.map((r:any)=>({...r,pix_key:decryptPixKey(r.pix_key)}));});
app.patch('/api/master/monthly-wallet/withdrawals/:id',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const b=body(req),status=String(b.status||'');if(!['paid','rejected'].includes(status))return reply.code(400).send({error:'Status deve ser pago ou recusado.'});const row=await one(`UPDATE gym_monthly_wallet_withdrawals SET status=$1,resolved_by=$2,resolved_at=now(),master_note=$3 WHERE id=$4 AND status='pending' RETURNING id,gym_id,amount,status,resolved_at,master_note`,[status,req.master!.id,String(b.master_note||'').slice(0,500),(req.params as any).id]);if(!row)return reply.code(404).send({error:'Solicitação pendente não encontrada.'});await q(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES($1,$2,$3,$4)`,[req.master!.id,'monthly_wallet_withdrawal_'+status,row.gym_id,JSON.stringify({withdrawal_id:row.id,amount:row.amount})]);return row;});
app.get('/api/master/gyms',{preHandler:[requireMaster,requireMasterReady]},async()=>q(`SELECT g.id,g.name,g.slug,g.active,g.archived_at,g.created_at,COUNT(DISTINCT s.id)::int student_count,COUNT(DISTINCT u.id)::int user_count FROM gyms g LEFT JOIN students s ON s.gym_id=g.id LEFT JOIN users u ON u.gym_id=g.id GROUP BY g.id ORDER BY g.created_at DESC`));
app.patch('/api/master/gyms/:id',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const b=body(req);if(typeof b.active!=='boolean')return reply.code(400).send({error:'Informe active como true/false.'});const id=(req.params as any).id,row=await one(`UPDATE gyms SET active=$1,archived_at=CASE WHEN $1 THEN NULL ELSE archived_at END,updated_at=now() WHERE id=$2 RETURNING id,name,slug,active,archived_at`,[b.active,id]);if(row)await q(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES($1,$2,$3,$4)`,[req.master!.id,b.active?'reactivate_gym':'block_gym',id,JSON.stringify({active:b.active})]);return row||reply.code(404).send({error:'Perfil não encontrado.'});});
app.post('/api/master/gyms/:id/archive',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const id=(req.params as any).id,row=await one(`UPDATE gyms SET active=false,archived_at=COALESCE(archived_at,now()),updated_at=now() WHERE id=$1 RETURNING id,name,slug,active,archived_at`,[id]);if(row)await q(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES($1,'archive_gym',$2,'{}')`,[req.master!.id,id]);return row||reply.code(404).send({error:'Perfil não encontrado.'});});
app.delete('/api/master/gyms/:id',{preHandler:[requireMaster,requireMasterReady]},async(req:MasterReq,reply)=>{const id=(req.params as any).id,client=await pool.connect();try{await client.query('BEGIN');const g=(await client.query(`SELECT id,name,slug FROM gyms WHERE id=$1 FOR UPDATE`,[id])).rows[0];if(!g){await client.query('ROLLBACK');return reply.code(404).send({error:'Perfil não encontrado.'});}await client.query(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES($1,'delete_gym',$2,$3)`,[req.master!.id,id,JSON.stringify({name:g.name,slug:g.slug})]);await client.query(`DELETE FROM gyms WHERE id=$1`,[id]);await client.query('COMMIT');return {ok:true,deleted:true,name:g.name,slug:g.slug};}catch(e){await client.query('ROLLBACK');app.log.error({err:e},'Master gym deletion failed');return reply.code(409).send({error:'Não foi possível excluir o perfil; verifique os vínculos existentes.'});}finally{client.release();}});
app.post('/api/master/logout',{preHandler:requireMaster},async(req:MasterReq)=>{const t=(req.headers.authorization||'').slice(7);await q(`UPDATE master_sessions SET revoked_at=now() WHERE token_hash=$1`,[hashToken(t)]);return {ok:true};});

const requireMp=()=>{if(!process.env.MP_ACCESS_TOKEN)throw new Error('Mercado Pago não está configurado no backend.');return process.env.MP_ACCESS_TOKEN;};
const mpRequest=async(path:string,method='GET',payload?:any)=>{const token=requireMp();const r=await fetch('https://api.mercadopago.com'+path,{method,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:payload?JSON.stringify(payload):undefined});const data:any=await r.json().catch(()=>({}));if(!r.ok)throw new Error(String(data.message||'Mercado Pago não aceitou a operação.'));return data;};
const asaasEnv=()=>process.env.ASAAS_ENV==='production'?'production':'sandbox';
const asaasBase=()=>asaasEnv()==='production'?'https://api.asaas.com/v3':'https://api-sandbox.asaas.com/v3';
const asaasRequest=async(path:string,method='GET',payload?:any)=>{const env=asaasEnv(),token=env==='production'?process.env.ASAAS_PRODUCTION_API_KEY:process.env.ASAAS_SANDBOX_API_KEY;if(!token)throw new Error(`Asaas ${env==='production'?'Produção':'Sandbox'} ainda não está configurado.`);const headers:Record<string,string>={'access_token':token,'Content-Type':'application/json','Accept':'application/json'};const r=await fetch(`${asaasBase()}${path}`,{method,headers,body:payload?JSON.stringify(payload):undefined});const data:any=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(String(data.errors?.[0]?.description||'Asaas não aceitou a operação.')),{statusCode:r.status,asaasErrors:data.errors||[]});return data;};
const asaasCustomer=async(gymId:string,student:any)=>{const studentId=String(student.id||student.student_id||'');if(!studentId)throw new Error('Aluno sem identificador para vincular ao Asaas.');let linked=await one(`SELECT customer_id FROM asaas_student_customers WHERE gym_id=$1 AND student_id=$2 AND environment=$3`,[gymId,studentId,asaasEnv()]);if(linked){try{const verified=await asaasRequest(`/customers/${encodeURIComponent(linked.customer_id)}`);if(verified?.id===linked.customer_id&&String(verified.cpfCnpj||'').replace(/\D/g,'')===String(student.cpf||'').replace(/\D/g,''))return linked.customer_id;await q(`DELETE FROM asaas_student_customers WHERE gym_id=$1 AND student_id=$2 AND environment=$3`,[gymId,studentId,asaasEnv()]);}catch(error:any){if(error?.statusCode!==404)throw error;await q(`DELETE FROM asaas_student_customers WHERE gym_id=$1 AND student_id=$2 AND environment=$3`,[gymId,studentId,asaasEnv()]);}}const env=asaasEnv(),externalReference=`mg:${env==='production'?'p':'s'}:${gymId}:${studentId}`;const found=await asaasRequest(`/customers?externalReference=${encodeURIComponent(externalReference)}`);let customer=found.data?.find((x:any)=>String(x.externalReference||'')===externalReference&&x.cpfCnpj&&String(x.cpfCnpj).replace(/\D/g,'')===String(student.cpf||'').replace(/\D/g,''));if(!customer){customer=await asaasRequest('/customers','POST',{name:String(student.full_name||'').slice(0,100),email:student.email||undefined,cpfCnpj:String(student.cpf||'').replace(/\D/g,''),externalReference});}if(!customer?.id)throw new Error('Asaas não retornou o cadastro do pagador.');await q(`INSERT INTO asaas_student_customers(gym_id,student_id,customer_id,environment) VALUES($1,$2,$3,$4) ON CONFLICT(gym_id,student_id,environment) DO UPDATE SET customer_id=excluded.customer_id,updated_at=now()`,[gymId,studentId,String(customer.id),asaasEnv()]);return String(customer.id);};
const asaasCreatePix=async({gymId,student,paymentId,amount,description,dueDate:requestedDueDate}:{gymId:string;student:any;paymentId:string;amount:number;description:string;dueDate?:string})=>{const customerId=await asaasCustomer(gymId,student),externalReference=`multigym-${asaasEnv()}-payment:${paymentId}`,due=new Date();let businessDays=0;while(businessDays<3){due.setDate(due.getDate()+1);if(due.getDay()!==0&&due.getDay()!==6)businessDays++;}const dueDate=requestedDueDate||due.toISOString().slice(0,10);const existing=await asaasRequest(`/payments?externalReference=${encodeURIComponent(externalReference)}`);const prior=(existing.data||[]).filter((x:any)=>String(x.externalReference||'')===externalReference);if(prior.some((x:any)=>String(x.customer||'')!==String(customerId)||money(x.value)!==money(amount)))throw new Error('Existe uma cobrança Asaas com esta referência, mas seus dados não correspondem à fatura.');let charge=prior.find((x:any)=>String(x.customer||'')===String(customerId)&&money(x.value)===money(amount));if(!charge){try{charge=await asaasRequest('/payments','POST',{customer:customerId,billingType:'PIX',value:money(amount),dueDate,description:description.slice(0,255),externalReference});}catch(error){const retry=await asaasRequest(`/payments?externalReference=${encodeURIComponent(externalReference)}`);const retryRows=(retry.data||[]).filter((x:any)=>String(x.externalReference||'')===externalReference);if(retryRows.some((x:any)=>String(x.customer||'')!==String(customerId)||money(x.value)!==money(amount)))throw new Error('Cobrança recuperada no Asaas não corresponde à fatura.');charge=retryRows.find((x:any)=>String(x.customer||'')===String(customerId)&&money(x.value)===money(amount));if(!charge)throw error;}}if(!charge?.id)throw new Error('Asaas não retornou a cobrança Pix.');const qr=await asaasRequest(`/payments/${encodeURIComponent(charge.id)}/pixQrCode`);await q(`UPDATE asaas_student_payments SET asaas_payment_id=$1,customer_id=$2,external_reference=$11,status=$3,invoice_url=$4,pix_copy_paste=$5,pix_qr_code_base64=$6,pix_expiration=$7,raw_response=$8,updated_at=now() WHERE payment_id=$9 AND environment=$10`,[String(charge.id),customerId,String(charge.status||'PENDING'),charge.invoiceUrl||null,qr.payload||null,qr.encodedImage||null,qr.expirationDate||null,JSON.stringify(charge),paymentId,asaasEnv(),externalReference]);return {charge,qr,customerId,externalReference};};
const asaasCreateFlexiblePayment=async({gymId,student,paymentId,amount,description,dueDate:requestedDueDate}:{gymId:string;student:any;paymentId:string;amount:number;description:string;dueDate?:string})=>{const customerId=await asaasCustomer(gymId,student),externalReference=`multigym-${asaasEnv()}-payment:${paymentId}`,due=new Date();let businessDays=0;while(businessDays<3){due.setDate(due.getDate()+1);if(due.getDay()!==0&&due.getDay()!==6)businessDays++;}const dueDate=requestedDueDate||due.toISOString().slice(0,10);const existing=await asaasRequest(`/payments?externalReference=${encodeURIComponent(externalReference)}`);const prior=(existing.data||[]).filter((x:any)=>String(x.externalReference||'')===externalReference);if(prior.some((x:any)=>String(x.customer||'')!==String(customerId)||money(x.value)!==money(amount)))throw new Error('Existe uma cobrança Asaas com esta referência, mas seus dados não correspondem à fatura.');let charge=prior.find((x:any)=>String(x.customer||'')===String(customerId)&&money(x.value)===money(amount));if(!charge){try{charge=await asaasRequest('/payments','POST',{customer:customerId,billingType:'UNDEFINED',value:money(amount),dueDate,description:description.slice(0,255),externalReference});}catch(error){const retry=await asaasRequest(`/payments?externalReference=${encodeURIComponent(externalReference)}`);const retryRows=(retry.data||[]).filter((x:any)=>String(x.externalReference||'')===externalReference);if(retryRows.some((x:any)=>String(x.customer||'')!==String(customerId)||money(x.value)!==money(amount)))throw new Error('Cobrança recuperada no Asaas não corresponde à fatura.');charge=retryRows.find((x:any)=>String(x.customer||'')===String(customerId)&&money(x.value)===money(amount));if(!charge)throw error;}}if(!charge?.id)throw new Error('Asaas não retornou o link de pagamento.');await q(`UPDATE asaas_student_payments SET asaas_payment_id=$1,customer_id=$2,external_reference=$8,status=$3,invoice_url=$4,raw_response=$5,updated_at=now() WHERE payment_id=$6 AND environment=$7`,[String(charge.id),customerId,String(charge.status||'PENDING'),charge.invoiceUrl||null,JSON.stringify(charge),paymentId,asaasEnv(),externalReference]);return {charge,customerId,externalReference};};
const asaasCreateCardPayment=async({gymId,student,paymentId,amount,description,dueDate,card,remoteIp}:{gymId:string;student:any;paymentId:string;amount:number;description:string;dueDate?:string;card:any;remoteIp:string})=>{if(!remoteIp||remoteIp==='127.0.0.1'||remoteIp==='::1')throw new Error('Não foi possível validar o IP da conexão para o pagamento seguro.');const customerId=await asaasCustomer(gymId,student),externalReference=`multigym-${asaasEnv()}-payment:${paymentId}`,existing=await asaasRequest(`/payments?externalReference=${encodeURIComponent(externalReference)}`),prior=(existing.data||[]).filter((x:any)=>String(x.externalReference||'')===externalReference);if(prior.some((x:any)=>String(x.customer||'')!==String(customerId)||money(x.value)!==money(amount)||String(x.billingType||'')!=='CREDIT_CARD'))throw new Error('Existe uma cobrança com esta referência, mas os dados não correspondem ao pagamento com cartão.');let charge=prior.find((x:any)=>String(x.customer||'')===String(customerId)&&money(x.value)===money(amount)&&String(x.billingType||'')==='CREDIT_CARD');if(!charge){const holder={name:String(card.holderName).trim(),email:String(student.email),cpfCnpj:String(student.cpf||'').replace(/\D/g,''),postalCode:String(card.postalCode).replace(/\D/g,''),addressNumber:String(card.addressNumber).trim(),phone:String(card.phone||'').replace(/\D/g,'')};const payload={customer:customerId,billingType:'CREDIT_CARD',value:money(amount),dueDate:dueDate||new Date(Date.now()+3*86400000).toISOString().slice(0,10),description:description.slice(0,255),externalReference,creditCard:{holderName:holder.name,number:String(card.number).replace(/\D/g,''),expiryMonth:String(card.expiryMonth).padStart(2,'0'),expiryYear:String(card.expiryYear),ccv:String(card.ccv)},creditCardHolderInfo:holder,remoteIp};charge=await asaasRequest('/payments','POST',payload);}if(!charge?.id)throw new Error('Asaas não retornou a cobrança do cartão.');const safe={id:String(charge.id),customer:String(charge.customer||customerId),externalReference:String(charge.externalReference||externalReference),value:money(charge.value),status:String(charge.status||'PENDING'),billingType:String(charge.billingType||'CREDIT_CARD'),invoiceUrl:charge.invoiceUrl||null,paymentDate:charge.paymentDate||null,confirmedDate:charge.confirmedDate||null};await q(`UPDATE asaas_student_payments SET asaas_payment_id=$1,customer_id=$2,external_reference=$3,status=$4,invoice_url=$5,raw_response=$6,updated_at=now() WHERE payment_id=$7 AND environment=$8`,[safe.id,customerId,externalReference,safe.status,safe.invoiceUrl,JSON.stringify(safe),paymentId,asaasEnv()]);return {charge:safe,customerId,externalReference};};
const settleAsaasPayment=async(asaasPaymentId:string,remote:any,eventId?:string,environment=asaasEnv())=>{const client=await pool.connect();try{await client.query('BEGIN');const linked=(await client.query(`SELECT a.*,p.status payment_status,p.amount,p.id local_payment_id,p.category,p.membership_period_start,p.membership_period_end FROM asaas_student_payments a JOIN payments p ON p.id=a.payment_id AND p.gym_id=a.gym_id WHERE a.asaas_payment_id=$1 AND a.environment=$2 FOR UPDATE OF a,p`,[asaasPaymentId,environment])).rows[0];if(!linked){await client.query('COMMIT');return false;}if(String(remote.externalReference||'')!==String(linked.external_reference)||String(remote.customer||'')!==String(linked.customer_id)||money(remote.value)!==money(linked.amount)){await client.query('ROLLBACK');throw new Error('Asaas payment does not match local reference, customer and amount');}if(linked.payment_status==='pending'&&String(remote.__event||'')==='PAYMENT_RECEIVED'&&String(remote.status)==='RECEIVED'){
// Serialize settlements for this gym, then record online receipts in the active cash
// register or create a clearly designated online-reconciliation register when closed.
await client.query(`SELECT id FROM gyms WHERE id=$1 FOR UPDATE`,[linked.gym_id]);
const paid=(await client.query(`UPDATE payments SET status='paid',method=$2,paid_at=COALESCE($1::timestamptz,now()),notes=concat(COALESCE(notes,''),' · Confirmado pelo Asaas') WHERE id=$3 AND gym_id=$4 AND status='pending' RETURNING id,enrollment_id,amount,method`,[remote.paymentDate||remote.confirmedDate||null,(remote.billingType==='CREDIT_CARD'?'card':remote.billingType==='PIX'?'pix':remote.billingType==='BOLETO'?'boleto':'other'),linked.local_payment_id,linked.gym_id])).rows[0];
if(paid){let register=(await client.query(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1 FOR UPDATE`,[linked.gym_id])).rows[0];if(!register){register=(await client.query(`INSERT INTO cash_registers(gym_id,opened_by,opening_amount,status,notes) VALUES($1,NULL,0,'open','Caixa de conciliação de pagamentos online Asaas; criado automaticamente para registrar recebimentos confirmados.') RETURNING id`,[linked.gym_id])).rows[0];}await client.query(`UPDATE asaas_student_payments SET cash_register_id=$1,updated_at=now() WHERE payment_id=$2 AND gym_id=$3 AND environment=$4 AND asaas_payment_id=$5`,[register.id,linked.local_payment_id,linked.gym_id,environment,asaasPaymentId]);await client.query(`INSERT INTO cash_movements(gym_id,register_id,type,direction,amount,method,description,reference_id,created_by) SELECT $1,$2,'payment','in',$3,$4,$5,$6,NULL WHERE NOT EXISTS(SELECT 1 FROM cash_movements WHERE gym_id=$1 AND type='payment' AND reference_id=$6)`,[linked.gym_id,register.id,paid.amount,paid.method,`Pagamento online MultiGym - ${linked.enrollment_id||paid.id}`,paid.id]);if(linked.category==='membership')await client.query(`UPDATE enrollments SET starts_on=CASE WHEN ends_on<CURRENT_DATE THEN COALESCE($3::date,CURRENT_DATE) ELSE starts_on END,ends_on=COALESCE($4::date,GREATEST(ends_on+1,CURRENT_DATE)+(SELECT duration_days-1 FROM plans WHERE id=enrollments.plan_id)),status='active',updated_at=now() WHERE id=$1 AND gym_id=$2`,[linked.enrollment_id,linked.gym_id,linked.membership_period_start,linked.membership_period_end]);else await client.query(`UPDATE enrollments SET status='active',updated_at=now() WHERE id=$1 AND gym_id=$2 AND status='pending'`,[linked.enrollment_id,linked.gym_id]);}
}
await client.query(`UPDATE asaas_student_payments SET status=$1,raw_response=$2,updated_at=now() WHERE asaas_payment_id=$3 AND environment=$4`,[String(remote.status||'PENDING'),JSON.stringify(remote),asaasPaymentId,environment]);if((['OVERDUE','DELETED','REFUNDED','CREDIT_CARD_CAPTURE_REFUSED','REPROVED_BY_RISK_ANALYSIS'].includes(String(remote.status))||['PAYMENT_CREDIT_CARD_CAPTURE_REFUSED','PAYMENT_REPROVED_BY_RISK_ANALYSIS'].includes(String(remote.__event||'')))&&linked.payment_status==='pending')await client.query(`UPDATE payments SET status='cancelled',notes=concat(COALESCE(notes,''),' · Asaas ', $1) WHERE id=$2 AND gym_id=$3 AND status='pending'`,[String(remote.status),linked.local_payment_id,linked.gym_id]);if(eventId)await client.query(`UPDATE asaas_webhook_events SET processed_at=now() WHERE event_id=$1`,[eventId]);await client.query('COMMIT');return true;}catch(e){await client.query('ROLLBACK').catch(()=>{});throw e}finally{client.release()}};
const mpLiveBillingReady=()=>process.env.MP_ORDERS_ENV==='production'&&Boolean(process.env.MP_ORDERS_PRODUCTION_ACCESS_TOKEN)&&Boolean(process.env.MP_ORDERS_WEBHOOK_SECRET)&&process.env.MP_ORDERS_LIVE_BILLING_ENABLED==='true';
const mpOrdersToken=()=>process.env.MP_ORDERS_ENV==='production'?process.env.MP_ORDERS_PRODUCTION_ACCESS_TOKEN:process.env.MP_ORDERS_ACCESS_TOKEN;
const mpOrdersRequest=async(path:string,method='GET',payload?:any)=>{const token=mpOrdersToken();if(!token)throw new Error('Mercado Pago Orders não configurado no backend.');const headers:Record<string,string>={Authorization:`Bearer ${token}`,'Content-Type':'application/json'};if(method==='POST')headers['X-Idempotency-Key']=crypto.randomUUID();const r=await fetch('https://api.mercadopago.com'+path,{method,headers,body:payload?JSON.stringify(payload):undefined});const data:any=await r.json().catch(()=>({}));if(!r.ok)throw new Error(String(data.message||'Mercado Pago não aceitou a operação.'));return data;};
const verifyMercadoPagoWebhook=(signature:string,requestId:string,dataId:string,secret:string)=>{
  if(!signature||!requestId||!dataId||!secret)return false;
  const parts=Object.fromEntries(signature.split(',').map((part)=>{const [key,...value]=part.trim().split('=');return [key,value.join('=')]}));
  if(!parts.ts||!parts.v1||!/^[a-f0-9]{64}$/i.test(parts.v1))return false;
  const manifest=`id:${dataId};request-id:${requestId};ts:${parts.ts};`;
  const expected=crypto.createHmac('sha256',secret).update(manifest).digest();
  const received=Buffer.from(parts.v1,'hex');
  return expected.length===received.length&&crypto.timingSafeEqual(expected,received);
};

const saasAccess=async(gymId:string)=>one(`SELECT s.gym_id,s.status,s.source,s.trial_started_at,s.expires_at,s.mp_preapproval_id,s.asaas_checkout_id,s.asaas_subscription_id,s.asaas_customer_id,s.asaas_external_reference,s.asaas_checkout_url,s.asaas_environment,s.asaas_amount,s.asaas_pending_plan_id,s.asaas_checkout_status,s.plan_id,p.name plan_name,p.monthly_price,p.plan_code,p.max_users FROM gym_saas_subscriptions s LEFT JOIN gym_saas_plans p ON p.id=s.plan_id WHERE s.gym_id=$1`,[gymId]);
const saasAllowed=(sub:any)=>{if(!sub)return true;if(sub.status==='grandfathered')return true;if(!sub.expires_at)return sub.status==='active';if(sub.trial_started_at&&new Date(sub.expires_at).getTime()>Date.now())return true;const expiry=new Date(`${String(sub.expires_at).slice(0,10)}T23:59:59-03:00`);if(sub.status==='active'&&expiry>=new Date())return true;expiry.setDate(expiry.getDate()+5);return expiry.getTime()>=Date.now()&&['active','manual','past_due','cancelled'].includes(sub.status);};
const saasAsaasReady=()=>Boolean(asaasEnv()==='production'?process.env.ASAAS_PRODUCTION_API_KEY:process.env.ASAAS_SANDBOX_API_KEY);
const saasReference=(gymId:string)=>`multigym-saas-${asaasEnv()}:${gymId}`;
const reconcileSaasSubscription=async(gymId:string)=>{const sub=await saasAccess(gymId);if(!sub?.asaas_subscription_id||sub.asaas_environment!==asaasEnv())return sub;try{const remote=await asaasRequest(`/subscriptions/${encodeURIComponent(sub.asaas_subscription_id)}`);if(String(remote.id)!==String(sub.asaas_subscription_id)||String(remote.externalReference||'')!==String(sub.asaas_external_reference)||String(remote.customer||'')!==String(sub.asaas_customer_id)||money(remote.value)!==money(sub.asaas_amount))throw new Error('Asaas subscription does not match its local gym, amount and reference');const payments=await asaasRequest(`/subscriptions/${encodeURIComponent(sub.asaas_subscription_id)}/payments`);const paid=(payments.data||[]).filter((x:any)=>String(x.subscription||'')===String(sub.asaas_subscription_id)&&String(x.customer||'')===String(sub.asaas_customer_id)&&money(x.value)===money(sub.asaas_amount)&&['RECEIVED','CONFIRMED'].includes(String(x.status))).sort((a:any,b:any)=>String(b.paymentDate||b.confirmedDate||'').localeCompare(String(a.paymentDate||a.confirmedDate||'')))[0];if(paid){const until=new Date(paid.paymentDate||paid.confirmedDate||Date.now());until.setMonth(until.getMonth()+1);await q(`UPDATE gym_saas_subscriptions SET plan_id=COALESCE(asaas_pending_plan_id,plan_id),asaas_pending_plan_id=NULL,asaas_checkout_status='PAID',status='active',source='asaas',trial_started_at=NULL,expires_at=GREATEST(COALESCE(expires_at,$1),$1),updated_at=now() WHERE gym_id=$2 AND asaas_subscription_id=$3 AND asaas_checkout_status IN ('PENDING','PAYMENT_PENDING','PAID')`,[until.toISOString(),gymId,sub.asaas_subscription_id]);}else if(['INACTIVE','EXPIRED'].includes(String(remote.status)))await q(`UPDATE gym_saas_subscriptions SET status='past_due',updated_at=now() WHERE gym_id=$1 AND asaas_subscription_id=$2 AND asaas_checkout_status='PAID' AND status<>'grandfathered'`,[gymId,sub.asaas_subscription_id]);}catch(e:any){app.log.warn({err:e,gym_id:gymId},'Asaas SaaS subscription reconciliation deferred');}return saasAccess(gymId);};
app.get('/api/saas/status',{preHandler:requireAuth},async(req:Req)=>{const sub=await reconcileSaasSubscription(req.user!.gym_id),tier=planTier(sub);const trial_days_remaining=sub?.trial_started_at&&sub.expires_at?Math.max(0,Math.ceil((new Date(sub.expires_at).getTime()-Date.now())/86400000)):null;const trial_started=sub?.trial_started_at?new Date(sub.trial_started_at).getTime():null;const show_trial_warning=trial_days_remaining!==null&&trial_started!==null&&Date.now()-trial_started>=7*86400000;return {subscription:sub,allowed:saasAllowed(sub),tier,features:{locked:lockedPlanFeatures[tier]||[],max_users:tier==='basic'?2:tier==='essential'?4:null},trial_days_remaining,show_trial_warning,provider_configured:saasAsaasReady(),billing_environment:asaasEnv()};});
app.post('/api/saas/checkout',{preHandler:[requireAuth,requireRoles(['admin'])],config:{rateLimit:{max:5,timeWindow:'10 minutes'}}},async(req:Req,reply)=>{const b=body(req),plan=await one(`SELECT id,name,monthly_price,active FROM gym_saas_plans WHERE id=$1 AND active=true`,[b.plan_id]);if(!plan)return reply.code(404).send({error:'Plano não encontrado ou indisponível.'});if(!saasAsaasReady())return reply.code(503).send({error:`Asaas ${asaasEnv()==='production'?'Produção':'Sandbox'} não está configurado para cobrança recorrente.`});try{const gymId=req.user!.gym_id,existing=await saasAccess(gymId);if(existing?.mp_preapproval_id)return reply.code(409).send({error:'Esta academia possui uma assinatura legada do Mercado Pago. Ela foi preservada e não será duplicada nem cancelada automaticamente; a migração precisa ser resolvida no Master antes de iniciar outra recorrência.'});if(existing?.asaas_subscription_id){if(existing.plan_id===plan.id&&existing.status==='active')return reply.code(409).send({error:'Este plano Asaas já está ativo.'});return reply.code(409).send({error:'Já existe uma assinatura Asaas para esta academia; a troca de plano precisa ser concluída sem criar uma recorrência duplicada.'});}if(existing?.asaas_checkout_id&&existing.asaas_checkout_status==='PENDING'&&existing.asaas_pending_plan_id===plan.id&&existing.asaas_environment===asaasEnv()&&existing.asaas_checkout_url&&existing.asaas_external_reference===saasReference(gymId)){if(String(existing.asaas_checkout_url).includes('?pagamento='))return {checkout_url:existing.asaas_checkout_url,pending:true};return reply.code(409).send({error:'Há uma tentativa de assinatura anterior aguardando resolução. Ela foi preservada para evitar recorrências duplicadas; contate o suporte.'});}if(existing?.asaas_checkout_id&&existing.asaas_checkout_status==='PENDING'&&existing.asaas_environment===asaasEnv())return reply.code(409).send({error:'Já existe um checkout Asaas pendente para outro plano.'});if(existing?.asaas_checkout_id&&existing.asaas_checkout_status==='PENDING'&&existing.asaas_environment!==asaasEnv())return reply.code(409).send({error:'Há um checkout pendente no outro ambiente do Asaas. Regularize-o antes de abrir outro para evitar cobranças duplicadas.'});const gym=await one(`SELECT id,name FROM gyms WHERE id=$1 AND active=true`,[gymId]);if(!gym)return reply.code(404).send({error:'Academia não encontrada ou inativa.'});const externalReference=saasReference(gymId),session=await createCheckoutSession({gymId,kind:'subscription',planId:plan.id,amount:Number(plan.monthly_price),metadata:{plan_name:plan.name}});const checkoutId=`multigym-${crypto.randomUUID()}`,checkoutUrl=session.url;await q(`UPDATE multigym_checkout_sessions SET metadata=metadata||$1::jsonb,updated_at=now() WHERE token_hash=$2`,[JSON.stringify({checkout_id:checkoutId}),hashToken(session.token)]);await q(`INSERT INTO gym_saas_subscriptions(gym_id,plan_id,status,source,asaas_checkout_id,asaas_customer_id,asaas_external_reference,asaas_checkout_url,asaas_environment,asaas_amount,asaas_pending_plan_id,asaas_checkout_status,updated_at) VALUES($1,$9,'pending','asaas',$3,$4,$5,$6,$7,$8,$2,'PENDING',now()) ON CONFLICT(gym_id) DO UPDATE SET asaas_checkout_id=excluded.asaas_checkout_id,asaas_customer_id=excluded.asaas_customer_id,asaas_external_reference=excluded.asaas_external_reference,asaas_checkout_url=excluded.asaas_checkout_url,asaas_environment=excluded.asaas_environment,asaas_amount=excluded.asaas_amount,asaas_pending_plan_id=excluded.asaas_pending_plan_id,asaas_checkout_status='PENDING',updated_at=now()`,[gymId,plan.id,checkoutId,'',externalReference,checkoutUrl,asaasEnv(),money(plan.monthly_price),existing?.plan_id||null]);return {checkout_url:checkoutUrl,provider:'multigym',environment:asaasEnv(),methods:['card'],recurrence:'MONTHLY',expires_at:session.expires_at};}catch(e:any){req.log.error({err:e},'Asaas SaaS checkout creation failed');return reply.code(502).send({error:e.message||'Não foi possível iniciar o checkout Asaas.'});}});
