app.post('/api/import/aroeira',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const b=body(req);const students=Array.isArray(b.students)?b.students:[];if(!students.length||students.length>1000)return reply.code(400).send({error:'Envie uma lista de alunos válida (1 a 1000).'});const g=req.user!.gym_id;const client=await pool.connect();const planMap=(raw:any)=>{const n=String(raw||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/’/g,"'").trim();if(n.includes('DIAR'))return {name:'Diária',days:1,price:14.99};if(n.includes('15 DIAS'))return {name:'Crédito 15 dias',days:15,price:0};if(n.includes('30 DIAS'))return {name:'Crédito 30 dias',days:30,price:0};if(n.includes('ANUAL'))return {name:'Plano anual',days:365,price:44.5};if(n.includes('1° MÊS')||n.includes('1 MES'))return {name:'Plano primeiro mês',days:30,price:59.9};if(n.includes('SEM PLANO')||!n)return null;return {name:'Plano mensal',days:30,price:69.9};};const result={received:students.length,created:0,updated:0,plans:0,enrollments:0,payments:0,errors:[] as any[]};try{await client.query('BEGIN');for(const item of students){try{const p=planMap(item.plan);let planId=null;if(p){const pr=await client.query(`INSERT INTO plans(gym_id,name,price,duration_days,description) VALUES($1,$2,$3,$4,$5) ON CONFLICT(gym_id,name) DO UPDATE SET price=EXCLUDED.price,updated_at=now() RETURNING id`,[g,p.name,p.price,p.days,`Importado da base Aroeira G Fitness`]);planId=pr.rows[0].id;if(pr.rowCount)result.plans++;}const name=String(item.name||'').trim();if(!name)throw new Error('Nome ausente');const email=String(item.email||'').trim().toLowerCase()||null;const phone=String(item.phone||'').trim()||null;let st=email?(await client.query('SELECT id FROM students WHERE gym_id=$1 AND lower(email)=lower($2) LIMIT 1',[g,email])).rows[0]:null;if(!st&&phone)st=(await client.query('SELECT id FROM students WHERE gym_id=$1 AND phone=$2 LIMIT 1',[g,phone])).rows[0];if(!st)st=(await client.query('SELECT id FROM students WHERE gym_id=$1 AND lower(full_name)=lower($2) LIMIT 1',[g,name])).rows[0];if(st){await client.query('UPDATE students SET full_name=$1,email=COALESCE($2,email),phone=COALESCE($3,phone),updated_at=now() WHERE id=$4 AND gym_id=$5',[name,email,phone,st.id,g]);result.updated++;}else{st=(await client.query('INSERT INTO students(gym_id,full_name,email,phone) VALUES($1,$2,$3,$4) RETURNING id',[g,name,email,phone])).rows[0];result.created++;}if(planId&&item.due){const due=String(item.due).slice(0,10);const amount=Number(item.value||0);const status=/atras|venc/i.test(String(item.payment||''))?'expired':(new Date(due)<new Date()?'expired':'active');const en=await client.query(`INSERT INTO enrollments(gym_id,student_id,plan_id,starts_on,ends_on,amount,status,notes) VALUES($1,$2,$3,($4::date-$5::int),$4,$6,$7,'Importado da base Aroeira G Fitness') RETURNING id`,[g,st.id,planId,due,p.days,amount,status]);if(en.rowCount)result.enrollments++;}for(const h of Array.isArray(item.paymentHistory)?item.paymentHistory:[]){const ref=`legacy:${item.id||name}:${String(h.date||'').slice(0,10)}`;const exists=await client.query('SELECT 1 FROM payments WHERE gym_id=$1 AND reference=$2 LIMIT 1',[g,ref]);if(!exists.rowCount) {const amount=Number(h.value||item.value||0);if(amount>0){await client.query(`INSERT INTO payments(gym_id,student_id,amount,paid_at,method,status,reference,notes) VALUES($1,$2,$3,$4,'other','paid',$5,'Importado da base Aroeira G Fitness')`,[g,st.id,amount,h.date||null,ref]);result.payments++;}}}}catch(e:any){result.errors.push({name:item.name||null,error:'Registro não importado'});}}await client.query('COMMIT');return reply.send(result);}catch(e){await client.query('ROLLBACK');return reply.code(400).send({error:'Não foi possível concluir a importação.'});}finally{client.release();}});
