app.get('/api/students',{preHandler:[requireAuth,requireStudentRead]},async(req:Req)=>{const s=String((req.query as any)?.search||'').trim().slice(0,120),status=String((req.query as any)?.status||'').trim(); if(req.user!.role==='instructor')return q(`SELECT s.id,s.full_name,s.status,s.training_level,s.training_experience_months,s.primary_goal,s.weekly_frequency,s.session_duration,s.limitations,s.preferences,e.id enrollment_id,e.ends_on,p.name plan_name FROM students s LEFT JOIN LATERAL(SELECT id,ends_on,plan_id FROM enrollments WHERE student_id=s.id AND gym_id=$1 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1)e ON true LEFT JOIN plans p ON p.id=e.plan_id WHERE s.gym_id=$1 AND ($2='' OR s.full_name ILIKE '%'||$2||'%') AND ($3='' OR s.status::text=$3) ORDER BY s.created_at DESC`,[req.user!.gym_id,s,status]);return q(`SELECT s.*,e.id enrollment_id,e.ends_on,e.amount,p.name plan_name FROM students s LEFT JOIN LATERAL(SELECT * FROM enrollments WHERE student_id=s.id AND gym_id=$1 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1)e ON true LEFT JOIN plans p ON p.id=e.plan_id WHERE s.gym_id=$1 AND ($2='' OR s.full_name ILIKE '%'||$2||'%' OR coalesce(s.cpf,'') ILIKE '%'||$2||'%' OR coalesce(s.phone,'') ILIKE '%'||$2||'%') AND ($3='' OR s.status::text=$3) ORDER BY s.created_at DESC`,[req.user!.gym_id,s,status]);});
