app.post('/api/team',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const b=body(req);if(!b.name||!b.email||!b.password||String(b.password).length<8)return reply.code(400).send({error:'Nome, e-mail e senha de pelo menos 8 caracteres são obrigatórios'});if(!['admin','manager','reception','instructor'].includes(b.role||'reception'))return reply.code(400).send({error:'Perfil inválido'});const client=await pool.connect();try{await client.query('BEGIN');const sub=(await client.query(`SELECT s.status,p.name plan_name,p.plan_code FROM gym_saas_subscriptions s LEFT JOIN gym_saas_plans p ON p.id=s.plan_id WHERE s.gym_id=$1 FOR UPDATE OF s`,[req.user!.gym_id])).rows[0],tier=planTier(sub),limit=tier==='basic'?2:tier==='essential'?4:null;if(limit!==null){const count=Number((await client.query(`SELECT count(*)::int count FROM users WHERE gym_id=$1 AND status='active'`,[req.user!.gym_id])).rows[0].count);if(count>=limit){await client.query('ROLLBACK');return reply.code(403).send({...planDenied('team_users'),error:`Seu plano permite até ${limit} usuários ativos (incluindo o administrador). Atualize seu plano para adicionar mais.`,upgrade_required:true,feature:'team_users',limit,current:count});}}const h=await argon2.hash(b.password),u=(await client.query(`INSERT INTO users(gym_id,name,email,password_hash,role) VALUES($1,$2,$3,$4,$5) RETURNING id,name,email,role,status`,[req.user!.gym_id,String(b.name).slice(0,160),b.email.toLowerCase(),h,b.role||'reception'])).rows[0];await client.query('COMMIT');return reply.code(201).send(u);}catch(e:any){await client.query('ROLLBACK').catch(()=>{});return reply.code(400).send({error:e?.code==='23505'?'E-mail já cadastrado':'Não foi possível criar o usuário.'});}finally{client.release();}});
app.put('/api/team/:id',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const b=body(req),id=(req.params as any).id;if(id===req.user!.id&&b.status==='inactive')return reply.code(400).send({error:'Você não pode inativar a própria conta.'});const client=await pool.connect();try{await client.query('BEGIN');const sub=(await client.query(`SELECT s.status,p.name plan_name,p.plan_code FROM gym_saas_subscriptions s LEFT JOIN gym_saas_plans p ON p.id=s.plan_id WHERE s.gym_id=$1 FOR UPDATE OF s`,[req.user!.gym_id])).rows[0],tier=planTier(sub),limit=tier==='basic'?2:tier==='essential'?4:null,target=(await client.query(`SELECT status,role FROM users WHERE id=$1 AND gym_id=$2`,[id,req.user!.gym_id])).rows[0];if(!target){await client.query('ROLLBACK');return reply.code(404).send({error:'Usuário não encontrado'});}if(req.user!.role==='manager'&&(target.role==='admin'||b.role==='admin'||(id===req.user!.id&&b.role!==undefined&&b.role!=='manager'))){await client.query('ROLLBACK');return reply.code(403).send({error:'Somente um administrador pode conceder ou alterar o perfil de administrador.'});}if(b.status!=='inactive'&&target.status!=='active'&&limit!==null){const count=Number((await client.query(`SELECT count(*)::int count FROM users WHERE gym_id=$1 AND status='active'`,[req.user!.gym_id])).rows[0].count);if(count>=limit){await client.query('ROLLBACK');return reply.code(403).send({...planDenied('team_users'),error:`Limite de ${limit} usuários ativos atingido. Atualize seu plano para reativar este usuário.`,upgrade_required:true,feature:'team_users',limit,current:count});}}const role=['admin','manager','reception','instructor'].includes(b.role)?b.role:null;if(!role){await client.query('ROLLBACK');return reply.code(400).send({error:'Perfil inválido'});}const hash=b.password&&String(b.password).length>=8?await argon2.hash(b.password):null,row=(await client.query(`UPDATE users SET name=$1,email=lower($2),role=$3,status=$4,password_hash=COALESCE($5,password_hash),updated_at=now() WHERE id=$6 AND gym_id=$7 RETURNING id,name,email,role,status,last_login_at,created_at`,[String(b.name||'').slice(0,160),b.email,role,b.status==='inactive'?'inactive':'active',hash,id,req.user!.gym_id])).rows[0];await client.query('COMMIT');return row;}catch(e:any){await client.query('ROLLBACK').catch(()=>{});return reply.code(400).send({error:e?.code==='23505'?'E-mail já cadastrado':'Não foi possível atualizar o usuário.'});}finally{client.release();}});
app.delete('/api/team/:id',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const id=(req.params as any).id;if(id===req.user!.id)return reply.code(400).send({error:'Você não pode remover a própria conta.'});const row=await one(`UPDATE users SET status='inactive',updated_at=now() WHERE id=$1 AND gym_id=$2 RETURNING id`,[id,req.user!.gym_id]);return row?{ok:true}:reply.code(404).send({error:'Usuário não encontrado'});});
app.get('/api/reports/overview',{preHandler:[requireAuth,requireManagement]},async(req:Req)=>{const g=req.user!.gym_id;const [monthly,plans,methods,attendance]=await Promise.all([q(`SELECT to_char(date_trunc('month',occurred_at),'YYYY-MM') AS "month",COALESCE(sum(amount) FILTER(WHERE status='paid'),0) revenue,COALESCE(sum(amount) FILTER(WHERE status='pending' AND operation='payment'),0) pending FROM (${FINANCIAL_OPERATIONS_SQL}) operations WHERE occurred_at>=now()-interval '12 months' GROUP BY 1 ORDER BY 1`,[g]),q(`SELECT pl.name,count(DISTINCT e.id)::int enrollments,COALESCE(sum(p.amount) FILTER(WHERE p.status='paid'),0) revenue FROM enrollments e JOIN plans pl ON pl.id=e.plan_id LEFT JOIN payments p ON p.enrollment_id=e.id AND p.gym_id=e.gym_id WHERE e.gym_id=$1 GROUP BY pl.name ORDER BY revenue DESC`,[g]),q(`SELECT method,count(*)::int count,COALESCE(sum(amount),0) total FROM (${FINANCIAL_OPERATIONS_SQL}) operations WHERE status='paid' GROUP BY method ORDER BY total DESC`,[g]),q(`SELECT to_char(date_trunc('day',checked_at),'YYYY-MM-DD') AS "day",count(*)::int checkins FROM checkins WHERE gym_id=$1 AND checked_at>=now()-interval '30 days' GROUP BY 1 ORDER BY 1`,[g])]);const tier=planTier(await gymSubscription(g));return {monthly,plans:tier==='basic'?[]:plans,methods,attendance};});

