app.post('/api/security/totp/setup',{preHandler:requireAuth},async(req:Req,reply)=>{const currentPassword=String(body(req).current_password||''),user=await one(`SELECT password_hash,totp_enabled FROM users WHERE id=$1`,[req.user!.id]);if(!user||!(await argon2.verify(user.password_hash,currentPassword)))return reply.code(401).send({error:'Confirme sua senha atual para configurar o aplicativo.'});if(user.totp_enabled)return reply.code(409).send({error:'A verificação já está ativa. Desative-a com senha e código antes de reconfigurar.'});const secret=newTotpSecret();await q(`UPDATE users SET totp_secret_encrypted=$1,updated_at=now() WHERE id=$2`,[encrypt(secret),req.user!.id]);const label=encodeURIComponent(`MultiGym:${req.user!.email}`),issuer=encodeURIComponent('MultiGym'),otpauth_url=`otpauth://totp/${label}?secret=${secret}&issuer=${issuer}&algorithm=SHA1&digits=6&period=30`;return {secret,otpauth_url};});
app.post('/api/security/totp/enable',{preHandler:requireAuth},async(req:Req,reply)=>{const row=await one(`SELECT totp_secret_encrypted FROM users WHERE id=$1`,[req.user!.id]);if(!row?.totp_secret_encrypted)return reply.code(400).send({error:'Inicie a configuração do aplicativo autenticador.'});let secret='';try{secret=decrypt(row.totp_secret_encrypted)}catch{return reply.code(400).send({error:'Não foi possível ler a configuração. Gere uma nova chave.'});}if(!verifyTotp(secret,String(body(req).totp_code||'')))return reply.code(400).send({error:'Código inválido. Confira a hora e a chave do aplicativo.'});await q(`UPDATE users SET totp_enabled=true,updated_at=now() WHERE id=$1`,[req.user!.id]);return {enabled:true};});
app.post('/api/security/totp/disable',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),row=await one(`SELECT password_hash,totp_enabled,totp_secret_encrypted FROM users WHERE id=$1`,[req.user!.id]);if(!row?.totp_enabled)return reply.code(400).send({error:'A verificação em duas etapas já está desativada.'});if(!(await argon2.verify(row.password_hash,String(b.password||''))))return reply.code(401).send({error:'Senha incorreta.'});let secret='';try{secret=decrypt(row.totp_secret_encrypted||'')}catch{return reply.code(401).send({error:'A chave de verificação precisa ser reconfigurada.'});}if(!verifyTotp(secret,String(b.totp_code||'')))return reply.code(401).send({error:'Código de verificação inválido.'});await q(`UPDATE users SET totp_secret_encrypted=NULL,totp_enabled=false,updated_at=now() WHERE id=$1`,[req.user!.id]);return {enabled:false};});
app.put('/api/security/password',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req);if(!b.current_password||!b.new_password||String(b.new_password).length<8)return reply.code(400).send({error:'Informe a senha atual e uma nova senha com pelo menos 8 caracteres.'});const u=await one(`SELECT password_hash FROM users WHERE id=$1 AND gym_id=$2`,[req.user!.id,req.user!.gym_id]);if(!u||!(await argon2.verify(u.password_hash,b.current_password)))return reply.code(400).send({error:'Senha atual inválida.'});const hash=await argon2.hash(b.new_password);await q(`UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2 AND gym_id=$3`,[hash,req.user!.id,req.user!.gym_id]);await q(`UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND token_hash<>$2 AND revoked_at IS NULL`,[req.user!.id,hashToken((req.headers.authorization||'').slice(7))]);return {ok:true};});

