app.put('/api/online-billing/settings',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const enabled=body(req).enabled;if(typeof enabled!=='boolean')return reply.code(400).send({error:'Informe se a cobrança online ficará ativada.'});if(enabled&&!((process.env.ASAAS_ENV==='sandbox'&&process.env.ASAAS_SANDBOX_API_KEY)||(process.env.ASAAS_ENV==='production'&&process.env.ASAAS_PRODUCTION_API_KEY)))return reply.code(503).send({error:'Cobranças Asaas aguardam uma chave válida para o ambiente selecionado.'});return one(`INSERT INTO gym_online_billing_settings(gym_id,enabled,updated_by,updated_at) VALUES($1,$2,$3,now()) ON CONFLICT(gym_id) DO UPDATE SET enabled=excluded.enabled,updated_by=excluded.updated_by,updated_at=now() RETURNING enabled,updated_at`,[req.user!.gym_id,enabled,req.user!.id]);});
app.post('/api/payments/asaas-checkout',{preHandler:[requireAuth,requireManagement],config:{rateLimit:{max:10,timeWindow:'10 minutes'}}},async(req:Req,reply)=>{const b=body(req),g=req.user!.gym_id,amount=money(b.amount),studentId=String(b.student_id||''),category=String(b.category||'other');if(!Number.isFinite(amount)||amount<=0||!studentId)return reply.code(400).send({error:'Selecione o aluno e informe um valor válido.'});if(!((process.env.ASAAS_ENV==='sandbox'&&process.env.ASAAS_SANDBOX_API_KEY)||(process.env.ASAAS_ENV==='production'&&process.env.ASAAS_PRODUCTION_API_KEY)))return reply.code(503).send({error:'Asaas não está configurado no ambiente selecionado.'});const register=await one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1`,[g]);if(!register)return reply.code(400).send({error:'Abra o caixa antes de gerar um link de pagamento.'});const student=await one(`SELECT id,full_name,cpf,email FROM students WHERE id=$1 AND gym_id=$2 AND status='active'`,[studentId,g]);if(!student)return reply.code(404).send({error:'Aluno não encontrado.'});if(!student.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(student.email))||String(student.cpf||'').replace(/\D/g,'').length!==11)return reply.code(400).send({error:'Cadastre CPF e e-mail válidos para gerar o link seguro.'});const enrollmentId=b.enrollment_id?String(b.enrollment_id):null;if(enrollmentId&&!await one(`SELECT id FROM enrollments WHERE id=$1 AND student_id=$2 AND gym_id=$3`,[enrollmentId,studentId,g]))return reply.code(400).send({error:'Matrícula inválida para este aluno.'});if(!['membership','enrollment','other'].includes(category))return reply.code(400).send({error:'Tipo de pagamento inválido.'});if(category==='membership')return reply.code(400).send({error:'Use uma fatura do ciclo para evitar cobrança duplicada.'});const paymentId=crypto.randomUUID(),externalReference=`multigym-${asaasEnv()}-payment:${paymentId}`,client=await pool.connect();try{await client.query('BEGIN');const payment=(await client.query(`INSERT INTO payments(id,gym_id,student_id,enrollment_id,amount,paid_at,method,status,category,reference,notes,created_by) VALUES($1,$2,$3,$4,$5,NULL,'other','pending',$6,$7,$8,$9) RETURNING *`,[paymentId,g,studentId,enrollmentId,amount,category,externalReference,'Aguardando pagamento online MultiGym (Pix/cartão)',req.user!.id])).rows[0];await client.query(`INSERT INTO asaas_student_payments(gym_id,student_id,enrollment_id,payment_id,customer_id,external_reference,status,environment,cash_register_id) VALUES($1,$2,$3,$4,'pending',$5,'PENDING',$6,$7)`,[g,studentId,enrollmentId,paymentId,externalReference,asaasEnv(),register.id]);await client.query('COMMIT');const checkout=await createCheckoutSession({gymId:g,kind:'payment',paymentId,amount,metadata:{purpose:category}});await audit(req.user!,'create','payment',paymentId,{payment_provider:'asaas',environment:asaasEnv()});return reply.code(201).send({payment,checkout_url:checkout.url,order_id:paymentId,status:'PENDING',amount,methods:['pix','card'],expires_at:checkout.expires_at});}catch(e:any){await client.query('ROLLBACK').catch(()=>{});req.log.error({err:e},'Asaas hosted payment creation failed');return reply.code(502).send({error:e.message||'Não foi possível gerar o link de pagamento.'});}finally{client.release();}});
app.get('/api/payments/:id/asaas-status',{preHandler:[requireAuth,requireCashAccess]},async(req:Req,reply)=>{const id=String((req.params as any).id),g=req.user!.gym_id,current=await one(`SELECT a.*,p.status payment_status,p.amount,p.due_at,p.membership_period_start,a.payment_method FROM asaas_student_payments a JOIN payments p ON p.id=a.payment_id AND p.gym_id=a.gym_id WHERE a.payment_id=$1 AND a.gym_id=$2 AND a.environment=$3`,[id,g,asaasEnv()]);if(!current)return reply.code(404).send({error:'Pagamento online não encontrado.'});if(current.payment_status==='pending'&&current.asaas_payment_id){try{const remote=await asaasRequest(`/payments/${encodeURIComponent(current.asaas_payment_id)}`);if(String(remote.externalReference||'')!==current.external_reference||String(remote.customer||'')!==current.customer_id||money(remote.value)!==money(current.amount))return reply.code(409).send({error:'A cobrança consultada não corresponde ao pagamento.'});if(remote.status==='RECEIVED'){remote.__event='PAYMENT_RECEIVED';await settleAsaasPayment(current.asaas_payment_id,remote);}else if(['DELETED','REFUNDED','OVERDUE'].includes(String(remote.status)))await q(`UPDATE payments SET status='cancelled',notes=concat(COALESCE(notes,''),' · Asaas ', $1) WHERE id=$2 AND gym_id=$3 AND status='pending'`,[remote.status,id,g]);}catch(e:any){req.log.error({err:e,payment_id:id},'Cash Asaas payment status check failed');return reply.code(502).send({error:'Não foi possível consultar o Asaas.'});}}return one(`SELECT p.id payment_id,p.status payment_status,p.method,p.amount,a.status order_status,a.invoice_url payment_url FROM asaas_student_payments a JOIN payments p ON p.id=a.payment_id AND p.gym_id=a.gym_id WHERE a.payment_id=$1 AND a.gym_id=$2 AND a.environment=$3`,[id,g,asaasEnv()]);});
app.get('/api/finance/monthly-wallet',{preHandler:[requireAuth,requireGymOwner]},async(req:Req)=>{const g=req.user!.gym_id;const settings=await one(`SELECT enabled FROM gym_online_billing_settings WHERE gym_id=$1`,[g]);const totals=await one(`SELECT COALESCE((SELECT sum(p.amount) FROM (SELECT payment_id,gym_id FROM mercadopago_student_orders UNION ALL SELECT payment_id,gym_id FROM asaas_student_payments WHERE environment='production') online JOIN payments p ON p.id=online.payment_id AND p.gym_id=online.gym_id WHERE online.gym_id=$1 AND p.status='paid' AND p.category='membership'),0) received,COALESCE((SELECT sum(amount) FROM gym_monthly_wallet_withdrawals WHERE gym_id=$1 AND status IN ('pending','paid')),0) reserved`,[g]);const payouts=(await q(`SELECT id,amount,pix_key,status,requested_at,resolved_at,master_note FROM gym_monthly_wallet_withdrawals WHERE gym_id=$1 ORDER BY requested_at DESC LIMIT 100`,[g])).map((r:any)=>({...r,pix_key:decryptPixKey(r.pix_key)}));const receivedPayments=await q(`SELECT p.id,p.amount,p.paid_at,s.full_name student_name FROM (SELECT payment_id,gym_id,student_id FROM mercadopago_student_orders UNION ALL SELECT payment_id,gym_id,student_id FROM asaas_student_payments WHERE environment='production') online JOIN payments p ON p.id=online.payment_id AND p.gym_id=online.gym_id JOIN students s ON s.id=online.student_id AND s.gym_id=online.gym_id WHERE online.gym_id=$1 AND p.status='paid' ORDER BY p.paid_at DESC LIMIT 100`,[g]);return {enabled:Boolean(settings?.enabled),received:Number(totals?.received||0),reserved:Number(totals?.reserved||0),available:Math.max(0,Number(totals?.received||0)-Number(totals?.reserved||0)),payouts,receivedPayments};});
app.post('/api/finance/monthly-wallet/withdrawals',{preHandler:[requireAuth,requireGymOwner]},async(req:Req,reply)=>{const g=req.user!.gym_id,b=body(req),amount=money(b.amount),pixKey=String(b.pix_key||'').trim().slice(0,200);if(!Number.isFinite(amount)||amount<=0||!pixKey)return reply.code(400).send({error:'Informe valor e chave Pix.'});const client=await pool.connect();try{await client.query('BEGIN');await client.query(`SELECT id FROM gyms WHERE id=$1 FOR UPDATE`,[g]);const totals=(await client.query(`SELECT COALESCE((SELECT sum(p.amount) FROM (SELECT payment_id,gym_id FROM mercadopago_student_orders UNION ALL SELECT payment_id,gym_id FROM asaas_student_payments WHERE environment='production') online JOIN payments p ON p.id=online.payment_id AND p.gym_id=online.gym_id WHERE online.gym_id=$1 AND p.status='paid' AND p.category='membership'),0) received,COALESCE((SELECT sum(amount) FROM gym_monthly_wallet_withdrawals WHERE gym_id=$1 AND status IN ('pending','paid')),0) reserved`,[g])).rows[0],available=money(Number(totals.received)-Number(totals.reserved));if(amount>available)throw new Error(`Saldo disponível: R$ ${available.toFixed(2)}.`);const row=(await client.query(`INSERT INTO gym_monthly_wallet_withdrawals(gym_id,amount,pix_key,requested_by) VALUES($1,$2,$3,$4) RETURNING id,amount,status,requested_at`,[g,amount,encryptPixKey(pixKey),req.user!.id])).rows[0];await client.query('COMMIT');return reply.code(201).send({...row,pix_key:pixKey});}catch(e:any){await client.query('ROLLBACK').catch(()=>{});return reply.code(400).send({error:e.message||'Não foi possível solicitar o saque.'});}finally{client.release();}});
app.get('/api/settings/gym',{preHandler:[requireAuth,requireManagementRead]},async(req:Req)=>one(`SELECT id,name,slug,logo_url,cnpj,phone,email,address,timezone FROM gyms WHERE id=$1`,[req.user!.gym_id]));
const logoValue=(value:any)=>{const v=String(value??'').trim();if(!v)return null;if(/^https?:\/\//i.test(v))return v.slice(0,2048);if(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/i.test(v)&&v.length<=700000)return v;return undefined;};
app.put('/api/settings/gym',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const b=body(req),logo=logoValue(b.logo_url);if(logo===undefined)return reply.code(400).send({error:'Logo inválido. Use PNG, JPG ou WEBP de até 512 KB.'});return one(`UPDATE gyms SET name=$1,logo_url=$2,cnpj=$3,phone=$4,email=$5,address=$6,timezone=$7,updated_at=now() WHERE id=$8 RETURNING *`,[String(b.name||'').slice(0,160),logo,String(b.cnpj||'').slice(0,18)||null,String(b.phone||'').slice(0,30)||null,String(b.email||'').slice(0,254)||null,b.address||{},b.timezone||'America/Sao_Paulo',req.user!.gym_id]);});


// Portal do aluno
const studentAuth = async (req:any, reply:FastifyReply) => {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return reply.code(401).send({error:'Não autenticado'});
  const row = await one(`SELECT sa.student_id,sa.gym_id,s.full_name,s.email,s.phone,s.cpf,s.photo_url,g.name gym_name,g.logo_url gym_logo_url FROM student_sessions ss JOIN student_accounts sa ON sa.id=ss.student_account_id JOIN students s ON s.id=sa.student_id JOIN gyms g ON g.id=sa.gym_id WHERE ss.token_hash=$1 AND ss.student_account_id=sa.id AND ss.gym_id=sa.gym_id AND sa.gym_id=s.gym_id AND s.gym_id=g.id AND ss.revoked_at IS NULL AND ss.expires_at>now() AND sa.status='active' AND s.status='active' AND g.active=true`, [hashToken(header.slice(7))]);
  if (!row) return reply.code(401).send({error:'Sessão expirada'}); req.student=row;const sub=await gymSubscription(row.gym_id),tier=planTier(sub);req.student.plan_tier=tier;const feature=featureForPath(req.url,req.method);if(feature&&(lockedPlanFeatures[tier]||[]).includes(feature))return reply.code(403).send(planDenied(feature));
};
app.post('/student-auth/login',{config:{rateLimit:{max:10,timeWindow:'10 minutes'}}},async(req,reply)=>{ const b=body(req); if(!b.gymSlug||!b.email||!b.password)return reply.code(400).send({error:'Informe academia, e-mail e senha'}); const account=await one(`SELECT sa.*,s.full_name,s.email student_email,s.phone,s.photo_url,g.name gym_name,g.logo_url gym_logo_url FROM student_accounts sa JOIN students s ON s.id=sa.student_id JOIN gyms g ON g.id=sa.gym_id WHERE g.slug=$1 AND lower(sa.email)=lower($2) AND sa.status='active' AND s.status='active' AND g.active=true`,[b.gymSlug,b.email]); if(!account)return reply.code(401).send({error:'E-mail ou senha inválidos'});if(account.locked_at)return reply.code(423).send({error:'Sua senha foi bloqueada por excesso de tentativas, entre em contato com a academia para solicitar o desbloqueio'});if(!(await argon2.verify(account.password_hash,b.password))){const failed=await one(`UPDATE student_accounts SET failed_login_attempts=failed_login_attempts+1,locked_at=CASE WHEN failed_login_attempts+1>=2 THEN now() ELSE locked_at END,updated_at=now() WHERE id=$1 RETURNING failed_login_attempts,locked_at`,[account.id]);if(failed?.locked_at){await q(`UPDATE student_sessions SET revoked_at=now() WHERE student_account_id=$1 AND revoked_at IS NULL`,[account.id]);return reply.code(423).send({error:'Sua senha foi bloqueada por excesso de tentativas, entre em contato com a academia para solicitar o desbloqueio'});}return reply.code(401).send({error:'E-mail ou senha inválidos'});}await q(`UPDATE student_accounts SET failed_login_attempts=0,locked_at=NULL WHERE id=$1`,[account.id]); const token=newToken(); await q(`INSERT INTO student_sessions(student_account_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '7 days')`,[account.id,account.gym_id,hashToken(token)]); await q(`UPDATE student_accounts SET last_login_at=now() WHERE id=$1`,[account.id]); return {token,student:{id:account.student_id,name:account.full_name,email:account.student_email||account.email,phone:account.phone,photoUrl:account.photo_url||null,gymName:account.gym_name,gymLogo:account.gym_logo_url||null}}; });
app.post('/api/students/:id/portal-access',{preHandler:[requireAuth,requireStudentRecords]},async(req:Req,reply)=>{ if(!['admin','manager','reception'].includes(req.user!.role))return reply.code(403).send({error:'Sem permissão'}); const b=body(req); if(!b.email||!b.password||String(b.password).length<8)return reply.code(400).send({error:'E-mail e senha de pelo menos 8 caracteres são obrigatórios'}); const student=await one(`SELECT id FROM students WHERE id=$1 AND gym_id=$2 AND status='active'`,[(req.params as any).id,req.user!.gym_id]); if(!student)return reply.code(404).send({error:'Aluno não encontrado'}); const h=await argon2.hash(b.password); await q(`INSERT INTO student_accounts(gym_id,student_id,email,password_hash,failed_login_attempts,locked_at) VALUES($1,$2,lower($3),$4,0,NULL) ON CONFLICT(student_id) DO UPDATE SET email=excluded.email,password_hash=excluded.password_hash,status='active',failed_login_attempts=0,locked_at=NULL,updated_at=now()`,[req.user!.gym_id,(req.params as any).id,b.email,h]);await q(`UPDATE student_sessions SET revoked_at=now() WHERE student_account_id=(SELECT id FROM student_accounts WHERE student_id=$1 AND gym_id=$2) AND revoked_at IS NULL`,[(req.params as any).id,req.user!.gym_id]); return reply.code(204).send(); });
app.post('/api/students/:id/portal-unlock',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const id=String((req.params as any).id),g=req.user!.gym_id,row=await one(`UPDATE student_accounts SET failed_login_attempts=0,locked_at=NULL,updated_at=now() WHERE student_id=$1 AND gym_id=$2 RETURNING id,email`,[id,g]);if(!row)return reply.code(404).send({error:'Este aluno não tem acesso ativo ao portal.'});await q(`UPDATE student_sessions SET revoked_at=now() WHERE student_account_id=$1 AND revoked_at IS NULL`,[row.id]);await audit(req.user!,'student_portal_unlocked','student',id,{email:row.email});return {ok:true,unlocked:true};});
app.post('/api/auth/locked-support',{config:{rateLimit:{max:3,timeWindow:'10 minutes'}}},async(req:any,reply)=>{const b=body(req),slug=String(b.gym_slug||'').trim().toLowerCase(),email=String(b.email||'').trim().toLowerCase(),phone=String(b.phone||'').trim();if(!slug||!email||!phone||phone.replace(/\D/g,'').length<8)return reply.code(400).send({error:'Informe academia, e-mail e telefone válidos.'});const account=await one(`SELECT u.id,u.gym_id,g.name gym_name FROM users u JOIN gyms g ON g.id=u.gym_id WHERE g.slug=$1 AND lower(u.email)=lower($2) AND u.locked_at IS NOT NULL AND u.status='active' AND g.active=true`,[slug,email]);if(!account)return reply.code(404).send({error:'Não foi encontrado um acesso de gestão bloqueado para estes dados.'});const existing=await one(`SELECT id FROM master_support_tickets WHERE gym_id=$1 AND locked_email=$2 AND locked_account_type='staff' AND status IN ('open','in_progress') ORDER BY created_at DESC LIMIT 1`,[account.gym_id,email]);if(existing)return reply.code(409).send({error:'Já existe uma solicitação de suporte para esta conta. O suporte entrará em contato em até 24hs.'});const contactEmail=String(b.contact_email||email).trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactEmail))return reply.code(400).send({error:'Informe um e-mail válido para contato.'});const subject='Solicitação de suporte: acesso da gestão bloqueado',description=`Solicitação automática por bloqueio de senha da gestão.\nE-mail para retorno: ${contactEmail}\nNúmero para contato: ${phone}\n\nAguarde, nosso suporte entrará em contato em até 24hs`;const ticket=await one(`INSERT INTO master_support_tickets(gym_id,gym_name,subject,description,priority,locked_email,locked_account_type) VALUES($1,$2,$3,$4,'high',$5,'staff') RETURNING id,subject,status,created_at`,[account.gym_id,account.gym_name,subject,description,email]);await q(`INSERT INTO master_support_messages(ticket_id,author_type,body) VALUES($1,'gym',$2)`,[ticket.id,description]);await q(`INSERT INTO master_audit_logs(master_id,action,gym_id,metadata) VALUES(NULL,'locked_staff_support_requested',$1,$2)`,[account.gym_id,JSON.stringify({ticket_id:ticket.id,email:contactEmail,phone})]);return reply.code(201).send({ok:true,ticket_id:ticket.id,message:'Aguarde, nosso suporte entrará em contato em até 24hs'});});
app.get('/student-api/brand',{preHandler:studentAuth},async(req:any)=>one(`SELECT name,logo_url FROM gyms WHERE id=$1 AND active=true`,[req.student.gym_id]));
app.post('/student-api/tts',{preHandler:studentAuth},async(req:any,reply)=>{const b=body(req),text=String(b.text||'').trim().slice(0,1600),assistant=b.assistant==='personalgym'?'personalgym':'nutrigym',key=process.env.ELEVENLABS_API_KEY;if(!text)return reply.code(400).send({error:'Texto de voz vazio.'});if(!key)return reply.code(503).send({error:'Voz neural ainda não configurada. O avatar continuará usando a voz do dispositivo.'});const voices:any={personalgym:'hpp4J3VqNfWAUOO0d1Us',nutrigym:'EXAVITQu4vr4xnSDxMaL'};try{const response=await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voices[assistant] || voices.nutrigym}?output_format=mp3_44100_128`,{method:'POST',headers:{'xi-api-key':key,'Content-Type':'application/json','Accept':'audio/mpeg'},body:JSON.stringify({text,model_id:'eleven_multilingual_v2',voice_settings:{stability:.5,similarity_boost:.82,style:.22,use_speaker_boost:true}})});if(!response.ok)return reply.code(502).send({error:'Não foi possível gerar a voz neural agora.'});const audio=Buffer.from(await response.arrayBuffer());return reply.header('Content-Type','audio/mpeg').header('Cache-Control','no-store').send(audio);}catch{return reply.code(502).send({error:'Não foi possível gerar a voz neural agora.'});}});
app.get('/student-api/announcements',{preHandler:studentAuth},async(req:any)=>q(`SELECT id,title,body,image_data,published_at FROM gym_announcements WHERE gym_id=$1 AND status='published' AND published_at<=now() ORDER BY published_at DESC LIMIT 20`,[req.student.gym_id]));
