app.post('/student-api/workouts/:id/complete',{preHandler:studentAuth},async(req:any,reply)=>{const id=(req.params as any).id;const own=await one(`SELECT id,name FROM workouts WHERE id=$1 AND student_id=$2 AND gym_id=$3 AND status='active'`,[id,req.student.student_id,req.student.gym_id]);if(!own)return reply.code(404).send({error:'Treino não encontrado'});const completion=await one(`INSERT INTO workout_completions(gym_id,student_id,workout_id) VALUES($1,$2,$3) RETURNING id,completed_at`,[req.student.gym_id,req.student.student_id,id]);await q(`UPDATE workouts SET status='inactive',updated_at=now() WHERE id=$1 AND gym_id=$2 AND student_id=$3`,[id,req.student.gym_id,req.student.student_id]);let next=await one(`SELECT id,name,objective,starts_on,source,routine_day,routine_cycle FROM workouts w WHERE student_id=$1 AND gym_id=$2 AND status='active' AND starts_on>CURRENT_DATE AND NOT EXISTS(SELECT 1 FROM workout_completions wc WHERE wc.workout_id=w.id AND wc.student_id=w.student_id) ORDER BY starts_on ASC,updated_at DESC LIMIT 1`,[req.student.student_id,req.student.gym_id]);if(!next)next=await generateAssistantWorkout(req.student.gym_id,req.student.student_id,1);const message=next?(next.source==='assistant'?`Treino concluído! 🔥 Você completou ${own.name}. Já preparei seu próximo treino: ${next.name}.`:`Treino concluído! 🔥 Você completou ${own.name}. Seu próximo treino já está disponível: ${next.name}.`):`Treino concluído! 🔥 Você completou ${own.name}. Não encontrei exercícios cadastrados suficientes para preparar a próxima sessão.`;await recordAssistantEvent(req.student.gym_id,req.student.student_id,'personalgym','WORKOUT_COMPLETED',{workout_id:id,completion_id:completion.id,next_workout:next,message});await q(`INSERT INTO personal_gym_chat_messages(gym_id,student_id,role,content) VALUES($1,$2,'assistant',$3)`,[req.student.gym_id,req.student.student_id,message]);return reply.code(201).send({...completion,assistant_event:{type:'WORKOUT_COMPLETED',message,next_workout:next}});});
app.get('/student-api/workouts/:id/logs',{preHandler:studentAuth},async(req:any)=>q(`SELECT id,workout_id,exercise_id,set_number,weight,reps,completed_at FROM workout_logs WHERE workout_id=$1 AND student_id=$2 ORDER BY completed_at DESC`,[(req.params as any).id,req.student.student_id]));
app.post('/student-api/workouts/:id/logs',{preHandler:studentAuth},async(req:any,reply)=>{const b=body(req),id=(req.params as any).id;if(!b.exercise_id||!Number.isInteger(Number(b.set_number))||Number(b.set_number)<1||Number(b.weight)<0||Number(b.reps)<1)return reply.code(400).send({error:'Informe exercício, série, carga e repetições válidos'});const own=await one(`SELECT w.id,e.name exercise_name,we.sets,we.rest FROM workouts w JOIN workout_exercises we ON we.workout_id=w.id AND we.gym_id=w.gym_id JOIN exercises e ON e.id=we.exercise_id WHERE w.id=$1 AND w.student_id=$2 AND w.gym_id=$3 AND w.status='active' AND we.exercise_id=$4`,[id,req.student.student_id,req.student.gym_id,b.exercise_id]);if(!own)return reply.code(404).send({error:'Exercício não pertence a este treino'});const row=await one(`INSERT INTO workout_logs(gym_id,student_id,workout_id,exercise_id,set_number,weight,reps) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,[req.student.gym_id,req.student.student_id,id,b.exercise_id,Number(b.set_number),Number(b.weight),Number(b.reps)]);const prescribedSets=parseInt(String(own.sets||''),10),isExerciseComplete=Number.isFinite(prescribedSets)&&Number(b.set_number)>=prescribedSets,eventType=isExerciseComplete?'EXERCISE_COMPLETED':'SET_COMPLETED',eventMessage=isExerciseComplete?`Exercício concluído: ${own.exercise_name}. Prepare-se para o próximo.`:`Série ${Number(b.set_number)} registrada. O descanso previsto é ${own.rest||'o definido pela academia'}.`,decision=decideAssistantAction({assistant:'personalgym',intent:'QUESTION',event:{type:eventType}});await recordAssistantEvent(req.student.gym_id,req.student.student_id,'personalgym',eventType,{workout_id:id,exercise_id:b.exercise_id,exercise_name:own.exercise_name,set_number:Number(b.set_number),weight:Number(b.weight),reps:Number(b.reps),message:eventMessage});return reply.code(201).send({...row,assistant_event:decision.shouldRespond?{type:eventType,message:eventMessage}:null});});
app.get('/student-api/progress',{preHandler:studentAuth},async(req:any)=>q(`SELECT measured_at,weight,height,body_fat,muscle_mass,arm,chest,waist,abdomen,hip,thigh,calf,notes FROM assessments WHERE student_id=$1 AND gym_id=$2 ORDER BY measured_at ASC`,[req.student.student_id,req.student.gym_id]));
app.put('/student-api/me',{preHandler:studentAuth},async(req:any,reply)=>{const b=body(req);if((b.phone===undefined&&b.photo_url===undefined)||b.photo_url!==undefined&&(typeof b.photo_url!=='string'||b.photo_url.length>700000||b.photo_url&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(b.photo_url)))return reply.code(400).send({error:'Dados de perfil inválidos.'});const row=await one(`UPDATE students SET phone=COALESCE($1,phone),photo_url=CASE WHEN $2::boolean THEN NULLIF($3,'') ELSE photo_url END,updated_at=now() WHERE id=$4 AND gym_id=$5 RETURNING id,full_name,email,phone,photo_url`,[b.phone===undefined?null:String(b.phone||'').slice(0,30),b.photo_url!==undefined,b.photo_url||null,req.student.student_id,req.student.gym_id]);return row?row:reply.code(404).send({error:'Perfil do aluno não encontrado.'});});


// NutriGym student module. The student and gym come exclusively from studentAuth;
// request bodies and tenant headers are never used as an authorization source.
const nutritionDate = (value:any) => {
  const v = String(value || '');
  if (!v) return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return undefined;
  const d = new Date(`${v}T00:00:00Z`);
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0,10) !== v ? undefined : v;
};
const nutritionNumber = (value:any, min:number, max:number, integer=false) => {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  if (!Number.isFinite(n) || n < min || n > max || (integer && !Number.isInteger(n))) return undefined;
  return n;
};
const nutritionText = (value:any, max:number, required=false) => {
  const v = String(value ?? '').trim();
  if (required && !v) return undefined;
  return v ? v.slice(0,max) : null;
};
const studentToday = async () => String((await one(`SELECT CURRENT_DATE::text today`))?.today);
const nutritionScope = (req:any) => ({gym:req.student.gym_id, student:req.student.student_id});
const recordAssistantEvent=async(gym:string,student:string,assistant:'nutrigym'|'personalgym',event_type:string,payload:any={})=>{try{await q(`INSERT INTO assistant_events(gym_id,student_id,assistant,event_type,payload) VALUES($1,$2,$3,$4,$5)`,[gym,student,assistant,event_type,JSON.stringify(payload)])}catch{app.log.warn({gym,student,assistant,event_type},'assistant event could not be recorded')}};
const normalizeWorkoutText=(value:any)=>String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
