const ensureAllExerciseLibraries=async()=>{const gyms=await q(`SELECT g.id FROM gyms g LEFT JOIN gym_exercise_catalog_versions v ON v.gym_id=g.id WHERE COALESCE(v.version,0)<$1`,[EXERCISE_CATALOG_VERSION]);let added=0;for(const gym of gyms)added+=await ensureExerciseLibrary(gym.id);app.log.info({academies:gyms.length,added,catalogSize:exerciseCatalog.length,version:EXERCISE_CATALOG_VERSION},'exercise library synchronized');};
