  const restrictions=context.profile?.allergies||context.profile?.restrictions,latest=rawContext.meals?.[0],hint=latest?` Seu último registro foi ${latest.meal_type.toLowerCase()}.`:'';
  let ai:string|null=null;let action:any=null;const lower=message.toLowerCase().trim();
  const waterMatch=lower.match(/^(?:bebi|tomei|adicionei|registrei)\\s+(?:água\\s+)?(\\d+(?:[.,]\\d+)?)\\s*(ml|mililitros|l|litros)\\b/);
  if(!imageDataUrl&&waterMatch){let amount=Number(waterMatch[1].replace(',','.'));if(['l','litros'].includes(waterMatch[2]))amount*=1000;if(amount>=1&&amount<=10000){await q(`INSERT INTO nutrigym_hydration(gym_id,student_id,hydration_date,amount_ml,hydration_time) VALUES($1,$2,CURRENT_DATE,$3,LOCALTIME)`,[s.gym,s.student,Math.round(amount)]);action={type:'hydration',amount_ml:Math.round(amount)};await recordAssistantEvent(s.gym,s.student,'nutrigym','HYDRATION_REGISTERED',{amount_ml:Math.round(amount),source:'chat'});}}
  const mealMatch=!imageDataUrl&&intent==='MEAL_REGISTRATION'&&!/[?？]/.test(message)&&!/^\\s*(?:será que|sera que|quanto|quanta|quantas|como|o que|por que|porque|quando)\\b/.test(lower)&&/^(?:comi|almocei|jantei|lanchei|tomei café|tomei cafe|fiz uma refeição|fiz uma refeicao)\\b/.test(lower);
  if(mealMatch){const type=lower.includes('café')||lower.includes('cafe')?'Café da manhã':lower.includes('almo')?'Almoço':lower.includes('jant')?'Jantar':lower.includes('lanche')?'Lanche':'Refeição',estimate=await estimateMealNutrition(message,type);await q(`INSERT INTO nutrigym_meals(gym_id,student_id,meal_date,meal_time,meal_type,description,calories,protein_g,carbs_g,fat_g,notes) VALUES($1,$2,CURRENT_DATE,LOCALTIME,$3,$4,$5,$6,$7,$8,$9)`,[s.gym,s.student,type,message,estimate.calories,estimate.protein_g,estimate.carbs_g,estimate.fat_g,'Registrada pelo chat; valores estimados por porção média']);action={type:'meal',meal_type:type};await recordAssistantEvent(s.gym,s.student,'nutrigym','MEAL_REGISTERED',{meal_type:type,source:'chat'});}
  if(!action&&!imageDataUrl&&intent!=='SAFETY'&&intent!=='PROFESSIONAL_REFERRAL'&&await allowAi(s.gym,'nutrigym_chat'))ai=await askAssistantNutrition(message,context);const fallback=imageDataUrl?nutritionFallback(context):action?.type==='hydration'?`Registrei ${action.amount_ml} ml de água. Sua hidratação já foi atualizada.`:action?.type==='meal'?`Registrei seu ${String(action.meal_type).toLowerCase()}. Se quiser, informe as quantidades para completar os dados.`:nutritionFallback(context);
  const safeFallback=fallback;const text=ai||safeFallback; await q(`INSERT INTO nutrigym_chat_messages(gym_id,student_id,role,content,has_image) VALUES($1,$2,'user',$3,$4),($1,$2,'assistant',$5,false)`,[s.gym,s.student,message,Boolean(imageDataUrl),text]);await saveExplicitMemory(s.gym,s.student,'nutrigym',message);await updateConversationState(s.gym,s.student,'nutrigym',intent);
  return {text,provider:ai?'groq':action?'rules':'fallback',action,context:{objective:context.profile?.objective||null,has_restrictions:Boolean(restrictions),recent_meals:context.nutrition?.recent_meals?.length||0,active_goals:context.goals?.length||0,has_plan:Boolean(context.nutrition?.plan),image_requested:Boolean(imageDataUrl),intent,memory_count:context.memory_notes?.length||0,knowledge_count:context.knowledge?.length||0,knowledge_sources:(context.knowledge||[]).map((r:any)=>({title:r.title,source:r.source_name,source_url:r.source_url,license:r.license_name})),tool_results:context.tool_results.map((tool:any)=>({tool:tool.tool,status:tool.status,source:tool.source,asOf:tool.asOf,recordCount:tool.recordCount,limitation:tool.limitation}))}};
