const nutritionContext=async(gym:string,student:string)=>{
  const [studentData,profile,meals,goals,checkin,checkinHistory,workouts,workoutHistory,assessments,hydration,memories,plan]=await Promise.all([
    one(`SELECT id,full_name,birth_date,gender,primary_goal,weekly_frequency,session_duration,training_level,training_experience_months,limitations,preferences FROM students WHERE gym_id=$1 AND id=$2`,[gym,student]),
    one(`SELECT id,objective,weight_kg,height_cm,age,sex,activity_level,calories_goal,protein_goal_g,carbs_goal_g,fat_goal_g,water_goal_ml,preferences,restrictions,allergies,dislikes,focus_areas,motivations,goal_weight_kg,body_type,body_fat_current,body_fat_goal,discomforts,wake_time,sleep_time,training_time,meals_per_day,budget_level,cooking_time FROM nutrigym_profiles WHERE gym_id=$1 AND student_id=$2`,[gym,student]),
    q(`SELECT id,meal_date,meal_type,description,meal_time,calories,protein_g,carbs_g,fat_g,notes,source,ai_analyzed,manual_correction FROM nutrigym_meals WHERE gym_id=$1 AND student_id=$2 AND meal_date>=CURRENT_DATE-interval '7 days' ORDER BY meal_date DESC,created_at DESC LIMIT 100`,[gym,student]),
    q(`SELECT goal_type,value,unit,period FROM nutrigym_goals WHERE gym_id=$1 AND student_id=$2 AND active=true`,[gym,student]),
    one(`SELECT mood,hunger,energy,night_hunger,sleep_quality,checkin_date FROM nutrigym_daily_checkins WHERE gym_id=$1 AND student_id=$2 ORDER BY checkin_date DESC LIMIT 1`,[gym,student]),
    q(`SELECT checkin_date,weight_kg,measurements,notes FROM nutrigym_checkins WHERE gym_id=$1 AND student_id=$2 ORDER BY checkin_date DESC LIMIT 12`,[gym,student]),
    q(`SELECT w.name,w.objective,w.review_on,w.starts_on FROM workouts w WHERE w.gym_id=$1 AND w.student_id=$2 AND w.status='active' ORDER BY w.updated_at DESC LIMIT 5`,[gym,student]),
    q(`SELECT wc.completed_at,w.name,w.objective FROM workout_completions wc JOIN workouts w ON w.id=wc.workout_id WHERE wc.gym_id=$1 AND wc.student_id=$2 ORDER BY wc.completed_at DESC LIMIT 12`,[gym,student]),
    q(`SELECT measured_at,weight,height,body_fat,muscle_mass,waist,chest,arm,thigh,notes FROM assessments WHERE gym_id=$1 AND student_id=$2 ORDER BY measured_at DESC LIMIT 12`,[gym,student]),
    q(`SELECT hydration_date,COALESCE(sum(amount_ml),0)::int amount_ml FROM nutrigym_hydration WHERE gym_id=$1 AND student_id=$2 AND hydration_date>=CURRENT_DATE-interval '7 days' GROUP BY hydration_date ORDER BY hydration_date DESC`,[gym,student]),
    q(`SELECT memory_key,memory_value FROM nutrigym_memories WHERE gym_id=$1 AND student_id=$2 AND active=true ORDER BY updated_at DESC LIMIT 20`,[gym,student]),
    one(`SELECT version,title,professional_name,status,content FROM nutrigym_plan_versions WHERE gym_id=$1 AND student_id=$2 AND status='active' ORDER BY version DESC LIMIT 1`,[gym,student])
  ]);
  return {today:await studentToday(),student:studentData,profile,meals,goals,checkin,checkinHistory,workouts,workoutHistory,assessments,hydration,memories,plan};
};
const personalContext=async(gym:string,student:string)=>{
 const [studentData,profile,workouts,workoutHistory,logs,assessments]=await Promise.all([
  one(`SELECT full_name,primary_goal,weekly_frequency,session_duration,training_level,training_experience_months,limitations,preferences FROM students WHERE gym_id=$1 AND id=$2`,[gym,student]),
  one(`SELECT objective,weight_kg,height_cm,activity_level,preferences,restrictions,discomforts,training_time FROM nutrigym_profiles WHERE gym_id=$1 AND student_id=$2`,[gym,student]),
  q(`SELECT w.id,w.name,w.objective,w.starts_on,w.review_on,w.notes,COALESCE(json_agg(json_build_object('id',x.id,'name',x.name,'muscle_group',x.muscle_group,'equipment',x.equipment,'instructions',x.instructions,'illustration_url',CASE WHEN x.illustration_url LIKE 'data:%' THEN NULL ELSE x.illustration_url END,'has_illustration',COALESCE(length(x.illustration_url),0)>0,'sets',we.sets,'reps',we.reps,'load',we.load,'rest',we.rest,'notes',we.notes) ORDER BY we.position) FILTER(WHERE x.id IS NOT NULL),'[]') exercises FROM workouts w LEFT JOIN workout_exercises we ON we.workout_id=w.id LEFT JOIN exercises x ON x.id=we.exercise_id WHERE w.gym_id=$1 AND w.student_id=$2 AND w.status='active' AND NOT EXISTS(SELECT 1 FROM workout_completions wc WHERE wc.workout_id=w.id AND wc.student_id=w.student_id) GROUP BY w.id ORDER BY (w.starts_on IS NULL OR w.starts_on<=CURRENT_DATE) DESC,w.starts_on ASC NULLS LAST,w.updated_at DESC LIMIT 1`,[gym,student]),
  q(`SELECT wc.workout_id,w.name,w.objective,wc.completed_at FROM workout_completions wc JOIN workouts w ON w.id=wc.workout_id WHERE wc.gym_id=$1 AND wc.student_id=$2 ORDER BY wc.completed_at DESC LIMIT 20`,[gym,student]),
  q(`SELECT wl.workout_id,wl.completed_at,wl.set_number,wl.weight,wl.reps,w.name workout_name,e.name exercise_name FROM workout_logs wl JOIN workouts w ON w.id=wl.workout_id JOIN exercises e ON e.id=wl.exercise_id WHERE wl.gym_id=$1 AND wl.student_id=$2 AND EXISTS(SELECT 1 FROM workout_completions wc WHERE wc.gym_id=wl.gym_id AND wc.student_id=wl.student_id AND wc.workout_id=wl.workout_id) ORDER BY wl.completed_at DESC LIMIT 60`,[gym,student]),
  q(`SELECT measured_at,weight,body_fat,muscle_mass,waist,notes FROM assessments WHERE gym_id=$1 AND student_id=$2 ORDER BY measured_at DESC LIMIT 8`,[gym,student]),
  q(`SELECT id,name,muscle_group,equipment,instructions FROM exercises WHERE gym_id=$1 AND active=true ORDER BY name LIMIT 200`,[gym])
 ]);return {today:await studentToday(),student:studentData,profile,workouts,workoutHistory,logs,assessments,exerciseCatalog};
};
